}
.lvl { font-family: var(--font); font-size: 9px; font-weight: 600; color: #849578; margin-left: 4px; vertical-align: 3px; }
.bond { display: flex; gap: 1px; margin-left: auto; margin-top: 7px; }
.bond span { font-size: 11px; line-height: 1; color: #d8cdb5; transition: color .2s ease, transform .2s ease; }
.bond span.on { color: #d97869; text-shadow: 0 1px 0 rgba(255,255,255,.5); }
.bond span.pop { transform: scale(1.35); }
.pal-line { margin: 5px 0 8px; font-size: 10px; line-height: 1.35; color: #77876c; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.needs { display: flex; flex-direction: column; gap: 5px; }
.need { display: flex; align-items: center; gap: 6px; }
.need-ico { width: 18px; height: 18px; padding: 3px; border-radius: 50%; flex: none; color: #fff; }
.need-ico.snack { background: #dc8c6f; }
.need-ico.joy { background: #e7b552; }
.need-ico.rest { background: #91a886; }
.need > div { flex: 1; min-width: 0; }
.need label { display: block; font-size: 8px; font-weight: 600; color: #849478; margin-bottom: 2px; text-transform: uppercase; letter-spacing: .8px; }
.meter-track.small { height: 5px; margin-top: 0; }
.meter-track.tiny { height: 4px; margin-top: 0; }
#hungerFill { background: linear-gradient(90deg, #e8ae82, #d77b68); }
#joyFill { background: linear-gradient(90deg, #f2d185, #e6ab4a); }
#energyFill { background: linear-gradient(90deg, #b4c49c, #7f9b79); }
.pal-xp { display: flex; align-items: center; gap: 6px; margin-top: 6px; font-size: 8px; color: #8b9b80; font-weight: 600; }
.pal-xp .meter-track { flex: 1; margin: 0; }
#palXpFill { background: linear-gradient(90deg, #c5b3d3, #9d88b9); }
.care-actions { grid-column: 1 / -1; display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; margin-top: 2px; }
.care-btn {
  height: 48px;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 9px;
  border-radius: 14px;
  color: #4d644e;
  background: rgba(255, 252, 242, .78);
  border: 1px solid rgba(81, 105, 72, .13);
