}
.care-btn:hover { transform: translateY(-2px); background: #fffdf6; box-shadow: 0 5px 12px rgba(62, 83, 52, .1); }
.care-btn:active { transform: scale(.96); }
.care-btn:disabled { opacity: .45; transform: none; }
.care-ico { width: 28px; height: 28px; padding: 5px; border-radius: 50%; flex: none; color: #fff; }
.care-btn.feed .care-ico { background: linear-gradient(145deg, #eb9f79, #d36b68); }
.care-btn.play .care-ico { background: linear-gradient(145deg, #f2cf75, #dfa946); }
.care-btn.pet .care-ico { background: linear-gradient(145deg, #e59a97, #c96467); }
.care-btn b { display: block; font-size: 11px; font-weight: 600; line-height: 1.05; }
.care-btn small { display: block; font-size: 8px; color: #93a087; margin-top: 2px; line-height: 1; }

/* ---------- sheets ---------- */
.modal-scrim {
  position: absolute;
  z-index: 31;
  inset: 0;
  background: rgba(38, 55, 38, .18);
  backdrop-filter: blur(2px);
  -webkit-backdrop-filter: blur(2px);
