}
@keyframes fade-in { from { opacity: 0; } }
.sheet {
  position: absolute;
  z-index: 40;
  left: 50%;
  bottom: calc(103px + var(--safe-bottom));
  transform: translateX(-50%);
  width: min(1080px, calc(100vw - 40px));
  max-height: min(62vh, 520px);
  padding: 20px 22px 16px;
  border-radius: 28px;
  background:
    radial-gradient(circle at 10% 0%, rgba(255,255,255,.48), transparent 30%),
    rgba(251, 245, 229, .97);
  border: 1px solid rgba(255,255,255,.85);
  box-shadow: 0 26px 70px rgba(42, 59, 35, .26), inset 0 1px 0 rgba(255,255,255,.9);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  animation: sheet-in .35s cubic-bezier(.2,1.2,.35,1);
}
@keyframes sheet-in { from { opacity: 0; transform: translate(-50%, 20px) scale(.97); } }
.sheet-head { display: flex; align-items: flex-end; gap: 20px; position: relative; padding-right: 44px; }
.sheet-head h2 {
  margin: 2px 0 0;
