  font-size: 27px;
  line-height: 1;
  font-weight: 600;
  letter-spacing: -.5px;
}
.sheet-sub { margin: 0 0 2px; font-size: 11px; line-height: 1.4; color: #7b8b70; max-width: 320px; }
.panel-close {
  width: 31px; height: 31px;
  padding: 8px;
  border-radius: 50%;
