}
.text-btn {
  display: inline-flex; align-items: center; gap: 4px;
  font-size: 11px; font-weight: 600; color: #4b6a4c;
  padding: 7px 4px;
}
.text-btn svg { width: 14px; height: 14px; }
.text-btn:hover { color: #2f4f38; }
.text-btn:hover svg { transform: translateX(2px); }
.text-btn svg { transition: transform .15s ease; }

/* build list */
.build-list {
  display: flex;
  gap: 9px;
