  overflow-x: auto;
  overflow-y: hidden;
  padding: 2px 2px 7px;
  scrollbar-width: none;
  touch-action: pan-x;
}
.build-list::-webkit-scrollbar { display: none; }
.build-card {
  position: relative;
  flex: 1 0 128px;
  min-width: 118px;
  max-width: 155px;
  padding: 5px 9px 10px;
  border-radius: 18px;
  text-align: left;
  background: rgba(255, 252, 244, .65);
  border: 1px solid rgba(81, 105, 72, .12);
