.build-cost.short { background: rgba(210, 100, 95, .1); color: #b85e5b; }
.build-card .owned-tag {
  position: absolute; top: 8px; right: 9px;
  padding: 3px 6px; border-radius: 999px;
  background: rgba(253, 248, 235, .9);
  font-size: 7px; text-transform: uppercase; letter-spacing: .9px; color: #7f9273;
  box-shadow: 0 1px 4px rgba(52, 74, 44, .1);
}
.build-foot { display: flex; align-items: center; justify-content: space-between; margin-top: 2px; }
.build-tip { display: flex; align-items: center; gap: 6px; font-size: 9px; color: #8b9a82; }
.build-tip i { width: 6px; height: 6px; border-radius: 50%; background: #97ad7d; box-shadow: 0 0 0 3px rgba(151,173,125,.15); }
#cancelBuild { color: #aa6b5d; }
.build-sheet.placing { box-shadow: 0 26px 70px rgba(42,59,35,.26), 0 0 0 2px rgba(235,183,86,.34), inset 0 1px 0 rgba(255,255,255,.9); }

/* pals grid */
.pals-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 10px; margin-top: 14px; }
.pal-card {
  position: relative;
  min-height: 158px;
  padding: 7px 8px 9px;
  border-radius: 18px;
  background: rgba(255,252,244,.65);
  border: 1px solid rgba(81,105,72,.12);
  text-align: left;
  transition: transform .18s ease, background .18s ease, box-shadow .18s ease;
  overflow: hidden;
}
.pal-card:hover { transform: translateY(-3px); background: #fffcf2; box-shadow: 0 10px 22px rgba(62,83,52,.11); }
.pal-card.active { background: #f3eed8; box-shadow: 0 0 0 2px rgba(197,168,100,.26); }
.pal-card.locked { cursor: default; background: rgba(242,240,226,.55); }
.pal-card.locked:hover { transform: none; box-shadow: none; }
.pal-card-canvas { width: 100%; height: 83px; display: block; }
.pal-card h4 { margin: 3px 3px 1px; font-family: var(--display); font-size: 15px; font-weight: 600; }
.pal-card .pc-sub { margin: 0 3px; font-size: 8px; color: #87957c; line-height: 1.3; min-height: 20px; }
.pc-needs { display: flex; gap: 3px; margin: 5px 3px 0; }
.pc-needs i { display: block; height: 4px; flex: 1; border-radius: 99px; background: rgba(76,97,66,.12); overflow: hidden; }
.pc-needs i span { display: block; height: 100%; border-radius: inherit; background: #d6a458; }
.pc-needs i:nth-child(1) span { background: #dc9474; }
.pc-needs i:nth-child(2) span { background: #e4b650; }
.pc-needs i:nth-child(3) span { background: #93aa7f; }
.pal-card.locked .lock-wrap { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px; color: #96a18a; background: rgba(242,239,226,.55); backdrop-filter: blur(2px); }
.lock-wrap svg { width: 23px; height: 23px; opacity: .7; }
.lock-wrap span { font-size: 8px; text-transform: uppercase; letter-spacing: 1.1px; font-weight: 600; }
.pal-card .pc-level { position: absolute; top: 10px; left: 11px; font-size: 8px; font-weight: 700; color: #7d906f; background: rgba(255,252,244,.84); padding: 2px 6px; border-radius: 99px; }
.pal-card .pc-mood { position: absolute; top: 10px; right: 11px; width: 7px; height: 7px; border-radius: 50%; background: #98ad7f; box-shadow: 0 0 0 2px rgba(255,252,244,.7); }
.pal-card .pc-mood.warn { background: #d99858; }
.pal-card .pc-mood.bad { background: #cf7068; }

/* journal */
.journal-sheet { width: min(940px, calc(100vw - 40px)); max-height: min(74vh, 620px); }
.journal-body { display: grid; grid-template-columns: 1.3fr .85fr; gap: 26px; margin-top: 16px; overflow: auto; padding-right: 4px; max-height: calc(74vh - 128px); scrollbar-width: thin; }
.journal-story { padding-right: 4px; }
.journal-illustration { position: relative; width: 100%; height: 145px; border-radius: 17px; overflow: hidden; background: linear-gradient(180deg,#dbe6cb,#f0e3bf); margin-bottom: 13px; }
#journalArt { width: 100%; height: 100%; display: block; }
.journal-story p { font-size: 11px; line-height: 1.65; color: #6f7f65; margin: 0 0 10px; }
.journal-story p.dropcap::first-letter { font-family: var(--display); font-size: 36px; line-height: .8; float: left; margin: 3px 5px 0 0; color: #5b7555; }
.journal-quote { padding: 12px 15px; margin-top: 13px; border-left: 3px solid #c5ab72; background: rgba(255,252,240,.55); border-radius: 2px 12px 12px 2px; font-family: var(--display); font-size: 13px; font-style: italic; color: #5c7053; line-height: 1.45; }
.journal-stats { border-left: 1px dashed rgba(93,114,79,.2); padding-left: 23px; }
.journal-stats h3 { margin: 0 0 9px; font-family: var(--display); font-size: 15px; font-weight: 600; color: #415c41; }
.stat-line { display: flex; justify-content: space-between; padding: 6px 0; border-bottom: 1px dotted rgba(93,114,79,.15); font-size: 10px; color: #7c8c71; }
.stat-line b { color: #486147; font-size: 11px; font-weight: 600; }
.how-list { margin-top: 16px; }
.how-list p { font-size: 9.5px; line-height: 1.5; margin: 0 0 7px; color: #7f8e75; }
.how-list b { color: #536b4f; }
.reset-btn { margin-top: 14px; font-size: 9px; color: #a57e72; text-decoration: underline; text-underline-offset: 2px; }
.reset-btn:hover { color: #a1544d; }

/* ---------- modals ---------- */
.welcome-card, .levelup-card, .confirm-card {
  position: absolute;
  z-index: 61;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: min(440px, calc(100vw - 32px));
  max-height: calc(100vh - 40px);
  overflow: auto;
  padding: 24px 25px 20px;
  border-radius: 28px;
  background:
    radial-gradient(circle at 90% 0%, rgba(255,255,255,.5), transparent 30%),
    rgba(252,246,231, .98);
  border: 1px solid rgba(255,255,255,.9);
  box-shadow: 0 28px 80px rgba(38,53,32,.28), inset 0 1px 0 rgba(255,255,255,.9);
  animation: modal-in .4s cubic-bezier(.2,1.25,.35,1);
  text-align: center;
}
@keyframes modal-in { from { opacity: 0; transform: translate(-50%, -46%) scale(.95); } }
.welcome-card h2, .levelup-card h2, .confirm-card h2 {
  margin: 2px 0 8px;
  font-family: var(--display);
  font-size: 30px;
  font-weight: 600;
  letter-spacing: -.6px;
  color: #36513a;
}
.welcome-card > p:not(.eyebrow), .levelup-card > p:not(.eyebrow), .confirm-card > p:not(.eyebrow) {
  margin: 0 auto 14px;
  max-width: 340px;
  font-size: 11px;
  line-height: 1.6;
  color: #74846a;
}
.welcome-art { width: calc(100% + 10px); margin: -9px -5px 12px; height: 130px; border-radius: 18px; overflow: hidden; background: linear-gradient(180deg,#d9e6cd,#f1e1bb); }
#welcomeArt { width: 100%; height: 100%; display: block; }
.welcome-tips { display: flex; flex-direction: column; gap: 8px; align-items: flex-start; width: max-content; max-width: 100%; margin: 0 auto 17px; text-align: left; }
.welcome-tips > span { display: flex; align-items: center; gap: 9px; font-size: 10px; color: #6e7f64; }
.tip-dot { width: 8px; height: 8px; border-radius: 50%; }
.dew-dot { background: #63a6a2; box-shadow: 0 0 0 3px rgba(99,166,162,.14); }
.leaf-dot { background: #849d6d; box-shadow: 0 0 0 3px rgba(132,157,109,.14); }
.spark-dot { background: #e4b155; box-shadow: 0 0 0 3px rgba(228,177,85,.16); }
.primary-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  min-height: 43px; padding: 9px 22px;
  border-radius: 999px;
  color: #fffbed;
  font-size: 12px; font-weight: 600;
  background: linear-gradient(145deg, #789063, #526f50);
  box-shadow: 0 7px 17px rgba(63,86,52,.22), inset 0 1px 0 rgba(255,255,255,.3);
  transition: transform .18s ease, box-shadow .18s ease;
}
.primary-btn:hover { transform: translateY(-2px); box-shadow: 0 11px 22px rgba(63,86,52,.28); }
.primary-btn:active { transform: scale(.97); }
.primary-btn svg { width: 16px; height: 16px; }
.welcome-later { display: block; margin: 7px auto 0; font-size: 9px; color: #98a28b; }
.welcome-later:hover { color: #6f8264; }

.level-up { position: absolute; z-index: 60; inset: 0; display: grid; place-items: center; background: rgba(47,65,41,.17); backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px); }
.level-up .levelup-card { position: relative; top: auto; left: auto; transform: none; animation: modal-in2 .6s cubic-bezier(.2,1.2,.35,1); text-align: center; }
@keyframes modal-in2 { 0% { opacity: 0; transform: scale(.8) rotate(-2deg); } 60% { opacity: 1; transform: scale(1.02) rotate(.4deg); } }
.levelup-rays {
  position: absolute; left: 50%; top: 50%;
  width: 790px; height: 790px;
  transform: translate(-50%,-50%);
