}
@keyframes spin-rays { to { transform: translate(-50%,-50%) rotate(360deg); } }
.levelup-card .eyebrow { color: #b0883c; }
.new-pal-row { display: grid; place-items: center; height: 164px; margin: -8px 0 4px; }
#newPalArt { width: 170px; height: 170px; filter: drop-shadow(0 9px 12px rgba(71,86,57,.14)); }
