export const TAU = Math.PI * 2;
export const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
export const lerp = (a, b, t) => a + (b - a) * t;

export function seeded(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function roundRect(ctx, x, y, w, h, r) {
  const rr = typeof r === "number" ? [r, r, r, r] : r;
  ctx.beginPath();
  ctx.moveTo(x + rr[0], y);
  ctx.lineTo(x + w - rr[1], y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rr[1]);
  ctx.lineTo(x + w, y + h - rr[2]);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rr[2], y + h);
  ctx.lineTo(x + rr[3], y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rr[3]);
  ctx.lineTo(x, y + rr[0]);
  ctx.quadraticCurveTo(x, y, x + rr[0], y);
  ctx.closePath();
}

export function heartPath(ctx, x, y, s) {
  ctx.beginPath();
  ctx.moveTo(x, y + s * 0.72);
  ctx.bezierCurveTo(x - s * 1.1, y - s * 0.05, x - s * 0.65, y - s * 0.9, x, y - s * 0.34);
  ctx.bezierCurveTo(x + s * 0.65, y - s * 0.9, x + s * 1.1, y - s * 0.05, x, y + s * 0.72);
  ctx.closePath();
}

export function starPath(ctx, x, y, r, points = 5, inner = 0.43, rotation = -Math.PI / 2) {
  ctx.beginPath();
  for (let i = 0; i < points * 2; i++) {
    const a = rotation + (i * Math.PI) / points;
    const rr = i % 2 ? r * inner : r;
    const px = x + Math.cos(a) * rr;
    const py = y + Math.sin(a) * rr;
    if (!i) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.closePath();
}

export function leafPath(ctx, x, y, w, h, rot = 0) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rot);
  ctx.beginPath();
  ctx.moveTo(0, -h / 2);
  ctx.bezierCurveTo(w * 0.8, -h * 0.3, w * 0.7, h * 0.35, 0, h / 2);
  ctx.bezierCurveTo(-w * 0.7, h * 0.35, -w * 0.8, -h * 0.3, 0, -h / 2);
  ctx.closePath();
  ctx.restore();
}

export function ellipse(ctx, x, y, rx, ry, fill, rot = 0) {
  ctx.beginPath();
  ctx.ellipse(x, y, rx, ry, rot, 0, TAU);
  if (fill) {
    ctx.fillStyle = fill;
    ctx.fill();
  }
}

export function softShadow(ctx, x, y, rx, ry, alpha = 0.16) {
  ctx.save();
  const g = ctx.createRadialGradient(x, y, 0, x, y, Math.max(rx, ry));
  g.addColorStop(0, `rgba(52, 68, 44, ${alpha})`);
  g.addColorStop(0.55, `rgba(52, 68, 44, ${alpha * 0.55})`);
  g.addColorStop(1, "rgba(52, 68, 44, 0)");
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(x, y, rx, ry, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function iso(view, c, r) {
  const ox = (COLS - 1) / 2;
  const oy = (ROWS - 1) / 2;
  return {
    x: view.cx + (c - r - ox + oy) * (TILE_W / 2) * view.scale,
    y: view.cy + (c + r - ox - oy) * (TILE_H / 2) * view.scale
  };
}

export function tileDiamond(view, c, r, inset = 0) {
  const p = iso(view, c, r);
  const hw = ((TILE_W / 2) * view.scale) - inset;
  const hh = ((TILE_H / 2) * view.scale) - inset * 0.5;
  return {
    top: { x: p.x, y: p.y - hh },
    right: { x: p.x + hw, y: p.y },
    bottom: { x: p.x, y: p.y + hh },
    left: { x: p.x - hw, y: p.y },
    center: p
  };
}

export function viewCorners(view) {
  const top = iso(view, 0, 0);
  const right = iso(view, COLS - 1, 0);
  const bottom = iso(view, COLS - 1, ROWS - 1);
  const left = iso(view, 0, ROWS - 1);
  const hw = (TILE_W / 2) * view.scale;
  const hh = (TILE_H / 2) * view.scale;
  return {
    T: { x: top.x, y: top.y - hh },
    R: { x: right.x + hw, y: right.y },
    B: { x: bottom.x, y: bottom.y + hh },
    L: { x: left.x - hw, y: left.y }
  };
}

export function bezierPath(ctx, pts, close = true) {
  ctx.beginPath();
  ctx.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i += 3) {
    if (pts[i + 2]) ctx.bezierCurveTo(pts[i][0], pts[i][1], pts[i + 1][0], pts[i + 1][1], pts[i + 2][0], pts[i + 2][1]);
  }
  if (close) ctx.closePath();
}

export function drawSparkle(ctx, x, y, r, color = "#f5d783", alpha = 1) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x, y - r);
  ctx.quadraticCurveTo(x + r * 0.16, y - r * 0.16, x + r, y);
  ctx.quadraticCurveTo(x + r * 0.16, y + r * 0.16, x, y + r);
  ctx.quadraticCurveTo(x - r * 0.16, y + r * 0.16, x - r, y);
  ctx.quadraticCurveTo(x - r * 0.16, y - r * 0.16, x, y - r);
  ctx.fill();
  ctx.restore();
}

export function drawHeart(ctx, x, y, s, color = "#dd8179", alpha = 1) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = color;
  heartPath(ctx, x, y, s);
  ctx.fill();
  ctx.restore();
}

export function drawStar(ctx, x, y, r, color = "#f1c568", alpha = 1) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = color;
  starPath(ctx, x, y, r);
  ctx.fill();
  ctx.restore();
}

export function drawDew(ctx, x, y, s, color = "#67aaa4", alpha = 1) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x, y - s);
  ctx.bezierCurveTo(x - s * 0.75, y - s * 0.2, x - s * 0.62, y + s * 0.7, x, y + s * 0.72);
  ctx.bezierCurveTo(x + s * 0.62, y + s * 0.7, x + s * 0.75, y - s * 0.2, x, y - s);
  ctx.fill();
  ctx.fillStyle = "rgba(255,255,255,.6)";
  ctx.beginPath();
  ctx.ellipse(x - s * 0.2, y + s * 0.08, s * 0.15, s * 0.27, -0.25, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function drawBerry(ctx, x, y, s, alpha = 1) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = "#d86966";
  ctx.beginPath();
  ctx.arc(x - s * 0.27, y + s * 0.1, s * 0.5, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(x + s * 0.3, y + s * 0.2, s * 0.46, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(x + s * 0.02, y - s * 0.22, s * 0.47, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "rgba(255,255,255,.32)";
  ctx.beginPath();
  ctx.arc(x - s * 0.4, y - s * 0.05, s * 0.1, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#5e7c53";
  leafPath(ctx, x + s * 0.12, y - s * 0.72, s * 0.4, s * 0.45, 0.65);
  ctx.fill();
  ctx.restore();
}

import { seeded, TAU, leafPath, roundRect } from "./art-core.js";

function cloud(ctx, x, y, s, alpha) {
  ctx.save();
  ctx.globalAlpha = alpha;
  const g = ctx.createRadialGradient(x, y, 2, x, y, 80 * s);
  g.addColorStop(0, "rgba(255,250,232,.9)");
  g.addColorStop(0.45, "rgba(250,244,222,.55)");
  g.addColorStop(1, "rgba(250,244,222,0)");
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(x, y, 100 * s, 29 * s, 0, 0, TAU);
  ctx.fill();
  ctx.globalAlpha = alpha * 0.65;
  ctx.fillStyle = "rgba(255,252,238,.7)";
  ctx.beginPath();
  ctx.ellipse(x - 30 * s, y - 9 * s, 36 * s, 19 * s, -0.08, 0, TAU);
  ctx.ellipse(x + 14 * s, y - 15 * s, 44 * s, 24 * s, 0.06, 0, TAU);
  ctx.ellipse(x + 56 * s, y - 4 * s, 28 * s, 15 * s, 0.12, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function ruin(ctx, x, ground, w, h, color, rnd, alpha = 0.58) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = color;
  ctx.beginPath();
  const notch = h * (0.18 + rnd() * 0.3);
  ctx.moveTo(x, ground);
  ctx.lineTo(x, ground - h + notch * 0.2);
  ctx.lineTo(x + w * 0.12, ground - h + notch * 0.05);
  ctx.lineTo(x + w * 0.26, ground - h + notch * (0.3 + rnd() * 0.5));
  ctx.lineTo(x + w * 0.42, ground - h + notch * 0.12);
  ctx.lineTo(x + w * 0.58, ground - h + notch * (0.5 + rnd() * 0.45));
  ctx.lineTo(x + w * 0.72, ground - h + notch * (0.15 + rnd() * 0.3));
  ctx.lineTo(x + w, ground - h + notch * 0.4);
  ctx.lineTo(x + w, ground);
  ctx.closePath();
  ctx.fill();

  // dark hollow windows
  ctx.globalAlpha = alpha * 0.35;
  ctx.fillStyle = "#4f6959";
  const cols = Math.max(1, Math.floor(w / 20));
  const rows = Math.max(1, Math.floor(h / 26));
  for (let c = 0; c < cols; c++) {
    for (let r = 0; r < rows; r++) {
      if (rnd() < 0.25) continue;
      ctx.fillRect(x + 8 + c * (w - 14) / cols, ground - h + 18 + r * (h - 25) / rows, Math.max(3, w / cols * 0.32), Math.max(5, h / rows * 0.23));
    }
  }

  // vines draped over the top
  ctx.globalAlpha = alpha * 0.72;
  ctx.strokeStyle = "#6f8d70";
  ctx.lineWidth = Math.max(1, w * 0.018);
  for (let i = 0; i < 3; i++) {
    const vx = x + w * (0.2 + rnd() * 0.7);
    const vy = ground - h + 10 + rnd() * 30;
    ctx.beginPath();
    ctx.moveTo(vx, vy);
    ctx.bezierCurveTo(vx + 5, vy + h * 0.2, vx - 9, vy + h * 0.35, vx + 2, vy + h * (0.4 + rnd() * 0.3));
    ctx.stroke();
    for (let k = 0; k < 3; k++) {
      const ly = vy + h * (0.14 + k * 0.13);
      ctx.fillStyle = "#7f9b76";
      leafPath(ctx, vx + (k % 2 ? 6 : -5), ly, 8, 11, k % 2 ? -0.5 : 0.5);
      ctx.fill();
    }
  }

  // mossy crown
  ctx.fillStyle = "#7f9b75";
  ctx.globalAlpha = alpha * 0.8;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.arc(x + w * (0.15 + rnd() * 0.72), ground - h + 3 + rnd() * 7, 8 + rnd() * 12, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function tinyFloatingIsle(ctx, x, y, s, rnd) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(s, s);
  ctx.globalAlpha = 0.75;
  // shadow / mist
  const mist = ctx.createRadialGradient(0, 26, 2, 0, 26, 83);
  mist.addColorStop(0, "rgba(244,239,215,.55)");
  mist.addColorStop(1, "rgba(244,239,215,0)");
  ctx.fillStyle = mist;
  ctx.beginPath();
  ctx.ellipse(0, 28, 90, 28, 0, 0, TAU);
  ctx.fill();
  // side
  ctx.fillStyle = "#7b6b50";
  ctx.beginPath();
  ctx.moveTo(-44, 5);
  ctx.quadraticCurveTo(-23, 47, 0, 58);
  ctx.quadraticCurveTo(23, 46, 44, 5);
  ctx.closePath();
  ctx.fill();
  // top
  ctx.fillStyle = "#8da872";
  ctx.beginPath();
  ctx.ellipse(0, 2, 48, 18, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#a8bd87";
  ctx.beginPath();
  ctx.ellipse(-7, -2, 35, 12, -0.04, 0, TAU);
  ctx.fill();
  // tiny dead tree
  ctx.strokeStyle = "#6c7a57";
  ctx.lineWidth = 2.3;
  ctx.beginPath();
  ctx.moveTo(11, 1);
  ctx.quadraticCurveTo(8, -26, 19, -39);
  ctx.moveTo(12, -18);
  ctx.lineTo(2, -29);
  ctx.moveTo(14, -25);
  ctx.lineTo(25, -32);
  ctx.stroke();
  ctx.fillStyle = "#91a97a";
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(14 + (rnd() - 0.5) * 30, -33 + (rnd() - 0.5) * 17, 4 + rnd() * 7, 0, TAU);
    ctx.fill();
  }
  // dangling roots
  ctx.strokeStyle = "rgba(97,101,71,.5)";
  ctx.lineWidth = 1;
  for (let i = 0; i < 3; i++) {
    const rx = -17 + i * 15;
    ctx.beginPath();
    ctx.moveTo(rx, 22);
    ctx.quadraticCurveTo(rx + 4, 37, rx - 3, 51 + rnd() * 10);
    ctx.stroke();
  }
  ctx.restore();
}

export function renderBackground(ctx, w, h) {
  const rnd = seeded(92941);
  const horizon = h * 0.435;
  const sunX = w * 0.77;
  const sunY = h * 0.15;

  // sky
  const sky = ctx.createLinearGradient(0, 0, 0, h);
  sky.addColorStop(0, "#a9c5b4");
  sky.addColorStop(0.28, "#c1d3bc");
  sky.addColorStop(0.56, "#e0dfbc");
  sky.addColorStop(0.78, "#f1dfb6");
  sky.addColorStop(1, "#ead5ad");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, w, h);

  // sun glow
  const sun = ctx.createRadialGradient(sunX, sunY, 4, sunX, sunY, Math.max(w, h) * 0.35);
  sun.addColorStop(0, "rgba(255,247,206,.98)");
  sun.addColorStop(0.09, "rgba(255,243,192,.9)");
  sun.addColorStop(0.28, "rgba(255,238,185,.34)");
  sun.addColorStop(0.62, "rgba(255,237,188,.08)");
  sun.addColorStop(1, "rgba(255,237,188,0)");
  ctx.fillStyle = sun;
  ctx.fillRect(0, 0, w, h);
  ctx.save();
  ctx.globalAlpha = 0.75;
  ctx.fillStyle = "#fff4c9";
  ctx.beginPath();
  ctx.arc(sunX, sunY, Math.min(w, h) * 0.047, 0, TAU);
  ctx.fill();
  ctx.restore();

  // warm beams
  ctx.save();
  ctx.globalCompositeOperation = "screen";
  ctx.globalAlpha = 0.16;
  const beam = ctx.createLinearGradient(sunX, sunY, sunX - w * 0.4, h * 0.75);
  beam.addColorStop(0, "rgba(255,241,186,.85)");
  beam.addColorStop(1, "rgba(255,241,186,0)");
  ctx.fillStyle = beam;
  ctx.beginPath();
  ctx.moveTo(sunX - w * 0.03, sunY);
  ctx.lineTo(sunX + w * 0.06, sunY + 24);
  ctx.lineTo(sunX - w * 0.3, h * 0.84);
  ctx.lineTo(sunX - w * 0.52, h * 0.84);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(sunX + w * 0.02, sunY + 10);
  ctx.lineTo(sunX + w * 0.09, sunY + 30);
  ctx.lineTo(sunX - w * 0.05, h * 0.8);
  ctx.lineTo(sunX - w * 0.19, h * 0.8);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  // clouds
  cloud(ctx, w * 0.16, h * 0.13, Math.min(1.2, w / 1100), 0.4);
  cloud(ctx, w * 0.6, h * 0.08, Math.min(0.85, w / 1500), 0.32);
  cloud(ctx, w * 0.92, h * 0.23, Math.min(0.72, w / 1700), 0.27);
  cloud(ctx, w * 0.38, h * 0.24, Math.min(0.6, w / 1900), 0.2);

  // far hills
  ctx.fillStyle = "#bccbb4";
  ctx.beginPath();
  ctx.moveTo(0, horizon - 10);
  ctx.bezierCurveTo(w * 0.13, horizon - 55, w * 0.24, horizon + 4, w * 0.4, horizon - 22);
  ctx.bezierCurveTo(w * 0.57, horizon - 56, w * 0.73, horizon + 9, w * 0.87, horizon - 16);
  ctx.bezierCurveTo(w * 0.94, horizon - 26, w * 0.98, horizon - 12, w, horizon - 18);
  ctx.lineTo(w, h);
  ctx.lineTo(0, h);
  ctx.closePath();
  ctx.fill();

  // ruins skyline
  ctx.save();
  const cityBase = horizon + 24;
  ruin(ctx, w * 0.035, cityBase, w * 0.075, h * 0.18, "#8fa78f", rnd, 0.37);
  ruin(ctx, w * 0.135, cityBase + 4, w * 0.055, h * 0.11, "#91a78e", rnd, 0.35);
  ruin(ctx, w * 0.24, cityBase, w * 0.08, h * 0.25, "#8fa68b", rnd, 0.42);
  ruin(ctx, w * 0.39, cityBase + 6, w * 0.06, h * 0.13, "#91a78d", rnd, 0.36);
  ruin(ctx, w * 0.57, cityBase + 2, w * 0.11, h * 0.2, "#8da58a", rnd, 0.37);
  ruin(ctx, w * 0.73, cityBase - 5, w * 0.07, h * 0.31, "#8ba289", rnd, 0.41);
  ruin(ctx, w * 0.88, cityBase + 6, w * 0.08, h * 0.17, "#90a78e", rnd, 0.34);
  ctx.restore();

  // old billboard, reclaimed by moss
  ctx.save();
  ctx.translate(w * 0.205, horizon - h * 0.08);
  ctx.rotate(-0.035);
  ctx.globalAlpha = 0.5;
  ctx.strokeStyle = "#788d75";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(-21, 6);
  ctx.lineTo(-15, h * 0.09);
  ctx.moveTo(22, 6);
  ctx.lineTo(24, h * 0.09);
  ctx.stroke();
  ctx.fillStyle = "#8ba188";
  roundRect(ctx, -48, -30, 96, 40, 4);
  ctx.fill();
  ctx.fillStyle = "rgba(241,238,211,.55)";
  ctx.font = "italic 13px Georgia, serif";
  ctx.textAlign = "center";
  ctx.fillText("breathe", 0, -6);
  ctx.fillStyle = "#7e9a79";
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(-37 + i * 18, -29 + rnd() * 5, 5 + rnd() * 7, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // distant overgrown trees
  ctx.save();
  ctx.globalAlpha = 0.55;
  const treeSpots = [0.08, 0.31, 0.5, 0.67, 0.84, 0.96];
  for (const spot of treeSpots) {
    const tx = w * spot + (rnd() - 0.5) * 20;
    const ty = horizon + 4 + rnd() * 14;
    ctx.strokeStyle = "#789070";
    ctx.lineWidth = 2.5;
    ctx.beginPath();
    ctx.moveTo(tx, ty);
    ctx.quadraticCurveTo(tx - 3, ty - 23, tx + 5, ty - 45 - rnd() * 18);
    ctx.stroke();
    ctx.fillStyle = "#8ba481";
    for (let i = 0; i < 4; i++) {
      ctx.beginPath();
      ctx.arc(tx + (rnd() - 0.5) * 36, ty - 38 - rnd() * 27, 10 + rnd() * 15, 0, TAU);
      ctx.fill();
    }
  }
  ctx.restore();

  // near hills
  const hillGrad = ctx.createLinearGradient(0, horizon + 50, 0, h);
  hillGrad.addColorStop(0, "#a8b98f");
  hillGrad.addColorStop(1, "#d3d2a8");
  ctx.fillStyle = hillGrad;
  ctx.beginPath();
  ctx.moveTo(0, horizon + 56);
  ctx.bezierCurveTo(w * 0.17, horizon + 13, w * 0.32, horizon + 94, w * 0.48, horizon + 45);
  ctx.bezierCurveTo(w * 0.65, horizon - 7, w * 0.82, horizon + 91, w, horizon + 45);
  ctx.lineTo(w, h);
  ctx.lineTo(0, h);
  ctx.closePath();
  ctx.fill();

  // mist band
  const mist = ctx.createLinearGradient(0, h * 0.52, 0, h * 0.8);
  mist.addColorStop(0, "rgba(247,239,212,0)");
  mist.addColorStop(0.45, "rgba(247,239,212,.3)");
  mist.addColorStop(1, "rgba(247,239,212,0)");
  ctx.fillStyle = mist;
  ctx.fillRect(0, h * 0.5, w, h * 0.32);

  // tiny floating isles
  tinyFloatingIsle(ctx, w * 0.085, h * 0.61, Math.min(0.78, w / 1400), rnd);
  tinyFloatingIsle(ctx, w * 0.935, h * 0.66, Math.min(0.56, w / 1800), rnd);

  // enormous soft framing foliage, upper corners
  ctx.save();
  ctx.filter = "blur(8px)";
  ctx.globalAlpha = 0.25;
  const leafy = ["#6f8b67", "#76926e", "#5f7c5d"];
  for (let i = 0; i < 17; i++) {
    ctx.fillStyle = leafy[i % 3];
    ctx.beginPath();
    ctx.arc(-30 + rnd() * 200, -40 + rnd() * 190, 22 + rnd() * 58, 0, TAU);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(w + 30 - rnd() * 190, -50 + rnd() * 180, 25 + rnd() * 55, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // fine framing branches at the very top
  ctx.save();
  ctx.globalAlpha = 0.38;
  ctx.strokeStyle = "#687e5d";
  ctx.lineWidth = 3.2;
  ctx.beginPath();
  ctx.moveTo(-10, 12);
  ctx.bezierCurveTo(w * 0.11, 28, w * 0.15, 60, w * 0.23, 84);
  ctx.stroke();
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(w * 0.085, 23);
  ctx.quadraticCurveTo(w * 0.1, 57, w * 0.13, 79);
  ctx.stroke();
  ctx.restore();

  // dew-warm vignette
  const vign = ctx.createRadialGradient(w * 0.5, h * 0.52, Math.min(w, h) * 0.2, w * 0.5, h * 0.52, Math.max(w, h) * 0.78);
  vign.addColorStop(0, "rgba(52,68,41,0)");
  vign.addColorStop(1, "rgba(52,68,41,.11)");
  ctx.fillStyle = vign;
  ctx.fillRect(0, 0, w, h);
}

export function drawBirds(ctx, w, h, t) {
  ctx.save();
  ctx.strokeStyle = "rgba(83,101,79,.42)";
  ctx.lineWidth = 1.3;
  ctx.lineCap = "round";
  const birds = [
    { x: 0.23, y: 0.22, s: 1.1, sp: 3.2, ph: 0.4 },
    { x: 0.55, y: 0.15, s: 0.7, sp: 2.4, ph: 2.0 },
    { x: 0.84, y: 0.29, s: 0.85, sp: 3.8, ph: 4.1 }
  ];
  for (let i = 0; i < birds.length; i++) {
    const b = birds[i];
    const drift = ((t * b.sp + i * 60) % (w + 220)) - 110;
    const x = (b.x * w + drift * 0.16) % (w + 80) - 20;
    const flap = Math.sin(t * 5 + b.ph) * 2.2;
    ctx.globalAlpha = 0.34 + 0.16 * Math.sin(t * 0.5 + i);
    ctx.beginPath();
    ctx.moveTo(x - 6 * b.s, b.y * h + flap);
    ctx.quadraticCurveTo(x - 3 * b.s, b.y * h - 2 * b.s, x, b.y * h);
    ctx.quadraticCurveTo(x + 3 * b.s, b.y * h - 2 * b.s, x + 6 * b.s, b.y * h + flap);
    ctx.stroke();
  }
  ctx.restore();
}

import {
  TILE_W, TILE_H, COLS, ROWS
} from "./data.js";
import {
  TAU, seeded, iso, tileDiamond, viewCorners, softShadow, leafPath, roundRect, drawSparkle
} from "./art-core.js";

function grassTuft(ctx, x, y, s, rnd, color = "#78955e") {
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = Math.max(0.8, 1.2 * s);
  ctx.lineCap = "round";
  for (let i = 0; i < 3 + Math.floor(rnd() * 3); i++) {
    const lean = (rnd() - 0.5) * 10 * s;
    ctx.beginPath();
    ctx.moveTo(x + (i - 1) * 2 * s, y);
    ctx.quadraticCurveTo(x + lean, y - 6 * s, x + lean * 1.3, y - (6 + rnd() * 7) * s);
    ctx.stroke();
  }
  ctx.restore();
}

function flower(ctx, x, y, s, rnd, color) {
  ctx.save();
  ctx.strokeStyle = "#72915d";
  ctx.lineWidth = Math.max(0.7, 0.9 * s);
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.quadraticCurveTo(x + 1.5 * s, y - 5 * s, x + (rnd() - 0.5) * 3 * s, y - 9 * s);
  ctx.stroke();
  const fy = y - 9.5 * s;
  const petal = 1.8 * s;
  ctx.fillStyle = color;
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * TAU + 0.3;
    ctx.beginPath();
    ctx.ellipse(x + Math.cos(a) * petal, fy + Math.sin(a) * petal * 0.75, petal * 0.85, petal * 0.55, a, 0, TAU);
    ctx.fill();
  }
  ctx.fillStyle = "#e6ba57";
  ctx.beginPath();
  ctx.arc(x, fy, petal * 0.5, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function mushroom(ctx, x, y, s, rnd) {
  ctx.save();
  const cap = (rnd() > 0.45 ? "#d7907e" : "#dfb47b");
  ctx.fillStyle = "#f0e6c9";
  ctx.beginPath();
  ctx.roundRect(x - 1.2 * s, y - 5 * s, 2.4 * s, 5 * s, 1.2 * s);
  ctx.fill();
  ctx.fillStyle = cap;
  ctx.beginPath();
  ctx.ellipse(x, y - 5 * s, 4.5 * s, 2.6 * s, 0, Math.PI, TAU);
  ctx.fill();
  ctx.fillStyle = "rgba(255,248,231,.7)";
  ctx.beginPath();
  ctx.arc(x - 1.3 * s, y - 6.1 * s, 0.7 * s, 0, TAU);
  ctx.arc(x + 1.4 * s, y - 5.7 * s, 0.55 * s, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function fern(ctx, x, y, s, rnd, color = "#6f8e5b") {
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = Math.max(0.8, 1.15 * s);
  ctx.lineCap = "round";
  const stems = 3 + Math.floor(rnd() * 3);
  for (let i = 0; i < stems; i++) {
    const a = -Math.PI / 2 + (i - (stems - 1) / 2) * 0.34;
    const len = (9 + rnd() * 7) * s;
    const ex = x + Math.cos(a) * len;
    const ey = y + Math.sin(a) * len;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.quadraticCurveTo(x + Math.cos(a) * len * 0.5 - 3 * s, y + Math.sin(a) * len * 0.5, ex, ey);
    ctx.stroke();
    for (let k = 1; k < 3; k++) {
      const t = k / 3;
      const lx = x + (ex - x) * t;
      const ly = y + (ey - y) * t;
      ctx.beginPath();
      ctx.moveTo(lx, ly);
      ctx.lineTo(lx + 3 * s, ly - 2 * s);
      ctx.moveTo(lx, ly);
      ctx.lineTo(lx - 3 * s, ly - 1.5 * s);
      ctx.stroke();
    }
  }
  ctx.restore();
}

function pebble(ctx, x, y, s, rnd) {
  ctx.save();
  const r = (1.4 + rnd() * 2.2) * s;
  ctx.fillStyle = rnd() > 0.5 ? "rgba(133,126,101,.55)" : "rgba(177,170,143,.5)";
  ctx.beginPath();
  ctx.ellipse(x, y, r, r * 0.58, rnd() * 2, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawCrackedSlab(ctx, view, c, r, rnd) {
  const p = iso(view, c, r);
  const s = view.scale;
  ctx.save();
  ctx.translate(p.x, p.y);
  ctx.fillStyle = "rgba(151,148,123,.58)";
  ctx.beginPath();
  ctx.moveTo(-28 * s, -7 * s);
  ctx.lineTo(27 * s, -3 * s);
  ctx.lineTo(30 * s, 11 * s);
  ctx.lineTo(-9 * s, 14 * s);
  ctx.lineTo(-27 * s, 8 * s);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = "rgba(99,102,82,.35)";
  ctx.lineWidth = 1 * s;
  ctx.beginPath();
  ctx.moveTo(-22 * s, -4 * s);
  ctx.lineTo(-9 * s, 0);
  ctx.lineTo(-12 * s, 8 * s);
  ctx.moveTo(4 * s, -4 * s);
  ctx.lineTo(12 * s, 2 * s);
  ctx.lineTo(21 * s, 0);
  ctx.stroke();
  ctx.fillStyle = "rgba(192,175,106,.48)";
  ctx.fillRect(-15 * s, 5 * s, 20 * s, 3 * s);
  grassTuft(ctx, -24 * s, 3 * s, s * 0.72, rnd, "#78955e");
  ctx.restore();
}

function drawSign(ctx, view, x, y, s) {
  ctx.save();
  ctx.translate(x, y);
  ctx.fillStyle = "rgba(74,84,59,.16)";
  ctx.beginPath();
  ctx.ellipse(0, 1, 23 * s, 7 * s, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = "#796e50";
  ctx.lineWidth = 3 * s;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(-2 * s, -34 * s);
  ctx.stroke();
  ctx.save();
  ctx.translate(-2 * s, -34 * s);
  ctx.rotate(-0.08);
  ctx.fillStyle = "#7d704f";
  roundRect(ctx, -23 * s, -11 * s, 44 * s, 17 * s, 3 * s);
  ctx.fill();
  ctx.strokeStyle = "rgba(236,223,183,.55)";
  ctx.lineWidth = 0.8 * s;
  ctx.stroke();
  ctx.fillStyle = "rgba(241,228,191,.84)";
  ctx.font = `600 ${5.2 * s}px Fredoka, sans-serif`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText("HOLLOW", 0, -2.2 * s);
  ctx.restore();
  ctx.fillStyle = "#6e8c5a";
  for (let i = 0; i < 3; i++) {
    leafPath(ctx, -4 * s + i * 4 * s, -17 * s, 4 * s, 6 * s, i * 0.4);
    ctx.fill();
  }
  ctx.restore();
}

export function renderIsland(ctx, view) {
  const scale = view.scale;
  const corners = viewCorners(view);
  const w = view.w;
  const h = view.h;
  const depth = Math.max(28, 74 * scale);
  const rnd = seeded(812367);
  const { T, R, B, L } = corners;

  // misty shadow beneath the floating sanctuary
  const shadowY = B.y + depth + 39 * scale;
  ctx.save();
  ctx.globalAlpha = 0.55;
  const bellyShadow = ctx.createRadialGradient(view.cx, shadowY, 5, view.cx, shadowY, (R.x - L.x) * 0.48);
  bellyShadow.addColorStop(0, "rgba(70,83,62,.25)");
  bellyShadow.addColorStop(0.52, "rgba(70,83,62,.12)");
  bellyShadow.addColorStop(1, "rgba(70,83,62,0)");
  ctx.fillStyle = bellyShadow;
  ctx.beginPath();
  ctx.ellipse(view.cx, shadowY, (R.x - L.x) * 0.47, 26 * scale, 0, 0, TAU);
  ctx.fill();
  ctx.restore();

  // underside rock mass
  ctx.save();
  const sideGrad = ctx.createLinearGradient(0, B.y - 20 * scale, 0, B.y + depth + 36 * scale);
  sideGrad.addColorStop(0, "#847053");
  sideGrad.addColorStop(0.42, "#776348");
  sideGrad.addColorStop(1, "#5b4c3a");
  ctx.fillStyle = sideGrad;
  ctx.beginPath();
  ctx.moveTo(L.x, L.y);
  ctx.lineTo(B.x, B.y);
  ctx.lineTo(R.x, R.y);
  ctx.lineTo(R.x - 4 * scale, R.y + depth);
  ctx.quadraticCurveTo(B.x + (R.x - B.x) * 0.48, B.y + depth + 27 * scale, B.x, B.y + depth + 36 * scale);
  ctx.quadraticCurveTo(B.x - (B.x - L.x) * 0.52, B.y + depth + 20 * scale, L.x + 3 * scale, L.y + depth);
  ctx.closePath();
  ctx.fill();

  // earthen strata
  ctx.save();
  ctx.clip();
  for (let i = 0; i < 9; i++) {
    ctx.globalAlpha = 0.08 + rnd() * 0.08;
    ctx.strokeStyle = i % 2 ? "#c3ab7c" : "#483d30";
    ctx.lineWidth = (0.7 + rnd() * 1.8) * scale;
    const yy = B.y - 2 + i * depth * 0.12;
    ctx.beginPath();
    ctx.moveTo(L.x + 12 * scale, yy + rnd() * 20 * scale);
    ctx.bezierCurveTo(view.cx - w * 0.16, yy + 7 * scale, view.cx + w * 0.15, yy - 8 * scale, R.x - 10 * scale, yy + rnd() * 16 * scale);
    ctx.stroke();
  }
  // embedded stones
  for (let i = 0; i < 16; i++) {
    const px = L.x + rnd() * (R.x - L.x);
    const py = B.y + 4 * scale + rnd() * depth * 1.05;
    ctx.globalAlpha = 0.18 + rnd() * 0.25;
    ctx.fillStyle = rnd() > 0.5 ? "#b7a788" : "#4d4438";
    ctx.beginPath();
    ctx.ellipse(px, py, (2 + rnd() * 5) * scale, (1.5 + rnd() * 3) * scale, rnd(), 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // roots spilling over the rim
  ctx.strokeStyle = "rgba(73,65,48,.7)";
  for (let i = 0; i < 9; i++) {
    const t = 0.1 + rnd() * 0.8;
    const sx = L.x + (R.x - L.x) * t;
    const sy = L.y + (R.x - L.x) * 0.5;
    const edgeY = B.y + (Math.abs(t - 0.5) * 2) * (depth * 0.55);
    ctx.lineWidth = (0.8 + rnd() * 1.5) * scale;
    ctx.beginPath();
    ctx.moveTo(sx, edgeY - 10 * scale);
    ctx.bezierCurveTo(sx + 2 * scale, edgeY + 12 * scale, sx - 7 * scale, edgeY + 20 * scale, sx + (rnd() - 0.5) * 8 * scale, edgeY + (24 + rnd() * 28) * scale);
    ctx.stroke();
  }
  // hanging vines
  for (let i = 0; i < 7; i++) {
    const t = 0.12 + rnd() * 0.76;
    const sx = L.x + (R.x - L.x) * t;
    const sy = B.y + (Math.abs(t - 0.5) * 2) * depth * 0.55;
    ctx.strokeStyle = "rgba(100,125,79,.55)";
    ctx.lineWidth = Math.max(0.7, 1.1 * scale);
    ctx.beginPath();
    ctx.moveTo(sx, sy);
    ctx.bezierCurveTo(sx + 5 * scale, sy + 16 * scale, sx - 8 * scale, sy + 24 * scale, sx + 1 * scale, sy + (35 + rnd() * 30) * scale);
    ctx.stroke();
    for (let k = 0; k < 3; k++) {
      ctx.fillStyle = "rgba(112,143,84,.55)";
      leafPath(ctx, sx + (k % 2 ? 5 : -4) * scale, sy + (13 + k * 9) * scale, 4 * scale, 6 * scale, k % 2 ? 0.7 : -0.5);
      ctx.fill();
    }
  }
  ctx.restore();

  // top face
  const topPath = new Path2D();
  topPath.moveTo(T.x, T.y);
  topPath.lineTo(R.x, R.y);
  topPath.lineTo(B.x, B.y);
  topPath.lineTo(L.x, L.y);
  topPath.closePath();

  ctx.save();
  ctx.clip(topPath);
  const base = ctx.createLinearGradient(T.x, T.y, B.x, B.y);
  base.addColorStop(0, "#97b07a");
  base.addColorStop(0.5, "#8aa66d");
  base.addColorStop(1, "#829e68");
  ctx.fillStyle = base;
  ctx.fillRect(L.x, T.y - 2, R.x - L.x, B.y - T.y + 4);

  // patchwork of meadow colours
  const meadow = ["#93ad75", "#8aa66d", "#91aa71", "#87a26a", "#97af79"];
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      const d = tileDiamond(view, c, r, 0);
      ctx.fillStyle = meadow[(c * 3 + r * 5 + Math.floor(rnd() * 2)) % meadow.length];
      ctx.globalAlpha = 0.22 + rnd() * 0.16;
      ctx.beginPath();
      ctx.moveTo(d.top.x, d.top.y);
      ctx.lineTo(d.right.x, d.right.y);
      ctx.lineTo(d.bottom.x, d.bottom.y);
      ctx.lineTo(d.left.x, d.left.y);
      ctx.closePath();
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;

  // broad sunlit and mossy areas
  const sunPatch = ctx.createRadialGradient(view.cx - 120 * scale, view.cy - 40 * scale, 10, view.cx - 70 * scale, view.cy - 10 * scale, 330 * scale);
  sunPatch.addColorStop(0, "rgba(209,216,155,.28)");
  sunPatch.addColorStop(1, "rgba(209,216,155,0)");
  ctx.fillStyle = sunPatch;
  ctx.fillRect(L.x, T.y, R.x - L.x, B.y - T.y);

  // organic dark moss pools
  for (let i = 0; i < 8; i++) {
    const p = iso(view, rnd() * (COLS - 1), rnd() * (ROWS - 1));
    const rx = (28 + rnd() * 62) * scale;
    const ry = rx * 0.42;
    ctx.globalAlpha = 0.08 + rnd() * 0.08;
    ctx.fillStyle = i % 3 === 0 ? "#536f4f" : "#6f8d5b";
    ctx.beginPath();
    ctx.ellipse(p.x, p.y, rx, ry, rnd(), 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  // faint builder grid
  ctx.strokeStyle = "rgba(60,81,51,.055)";
  ctx.lineWidth = 1;
  for (let r = 0; r <= ROWS; r++) {
    const a = iso(view, -0.5, r - 0.5);
    const b = iso(view, COLS - 0.5, r - 0.5);
    ctx.beginPath();
    ctx.moveTo(a.x, a.y);
    ctx.lineTo(b.x, b.y);
    ctx.stroke();
  }
  for (let c = 0; c <= COLS; c++) {
    const a = iso(view, c - 0.5, -0.5);
    const b = iso(view, c - 0.5, ROWS - 0.5);
    ctx.beginPath();
    ctx.moveTo(a.x, a.y);
    ctx.lineTo(b.x, b.y);
    ctx.stroke();
  }

  // old cracked slab find
  drawCrackedSlab(ctx, view, 1.15, 1.2, rnd);
  drawCrackedSlab(ctx, view, 5.85, 4.65, rnd);

  // stepping stones to the fire
  const pathTiles = [[4.15, 5.25], [3.8, 4.8], [3.4, 4.35], [4.1, 4.05], [4.55, 3.55]];
  for (let i = 0; i < pathTiles.length; i++) {
    const p = iso(view, pathTiles[i][0], pathTiles[i][1]);
    ctx.fillStyle = i % 2 ? "rgba(177,166,137,.6)" : "rgba(162,154,126,.62)";
    ctx.beginPath();
    ctx.ellipse(p.x + (rnd() - 0.5) * 8 * scale, p.y + (rnd() - 0.5) * 4 * scale, (12 + rnd() * 6) * scale, (5 + rnd() * 3) * scale, rnd() * 0.6, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = "rgba(102,100,78,.16)";
    ctx.lineWidth = 0.7 * scale;
    ctx.stroke();
  }

  // little clover, flowers and mushrooms scattered through the meadow
  const flowerColors = ["#f4e6c8", "#efb4a3", "#e9d18a", "#cbb7d8"];
  for (let i = 0; i < 26; i++) {
    const c = rnd() * (COLS - 0.2) - 0.4;
    const r = rnd() * (ROWS - 0.2) - 0.4;
    const p = iso(view, c, r);
    const kind = rnd();
    if (kind < 0.42) grassTuft(ctx, p.x, p.y, scale, rnd);
    else if (kind < 0.72) flower(ctx, p.x, p.y, scale, rnd, flowerColors[Math.floor(rnd() * flowerColors.length)]);
    else if (kind < 0.86) pebble(ctx, p.x, p.y, scale, rnd);
    else mushroom(ctx, p.x, p.y, scale * 0.9, rnd);
  }

  // lush edge fringe
  ctx.strokeStyle = "rgba(105,135,80,.52)";
  ctx.lineWidth = Math.max(1, 1.4 * scale);
  const edges = [
    [L, B], [B, R], [R, T], [T, L]
  ];
  for (let i = 0; i < 4; i++) {
    const [a, b] = edges[i];
    ctx.beginPath();
    ctx.moveTo(a.x, a.y);
    ctx.lineTo(b.x, b.y);
    ctx.stroke();
    const count = i < 2 ? 18 : 10;
    for (let k = 0; k < count; k++) {
      const t = (k + rnd() * 0.8) / count;
      const x = a.x + (b.x - a.x) * t;
      const y = a.y + (b.y - a.y) * t;
      grassTuft(ctx, x, y + (i < 2 ? 1 : 0), scale * 0.8, rnd, i === 0 ? "#66864f" : "#7e9a62");
    }
  }

  // stones around the edge
  for (let i = 0; i < 20; i++) {
    const t = rnd();
    const edge = i % 4;
    let x;
    let y;
    if (edge === 0) { x = L.x + (B.x - L.x) * t; y = L.y + (B.y - L.y) * t; }
    else if (edge === 1) { x = B.x + (R.x - B.x) * t; y = B.y + (R.y - B.y) * t; }
    else if (edge === 2) { x = L.x + (T.x - L.x) * t; y = L.y + (T.y - L.y) * t; }
    else { x = T.x + (R.x - T.x) * t; y = T.y + (R.y - T.y) * t; }
    ctx.fillStyle = rnd() > 0.5 ? "rgba(130,128,103,.52)" : "rgba(108,119,86,.48)";
    ctx.beginPath();
    ctx.ellipse(x + (rnd() - 0.5) * 8 * scale, y + (rnd() - 0.5) * 4 * scale, (3.5 + rnd() * 5) * scale, (2 + rnd() * 3) * scale, rnd(), 0, TAU);
    ctx.fill();
  }

  // back edge lichen
  ctx.strokeStyle = "rgba(108,88,61,.7)";
  ctx.lineWidth = Math.max(1.5, 3.2 * scale);
  ctx.beginPath();
  ctx.moveTo(L.x, L.y + 1 * scale);
  ctx.lineTo(B.x, B.y + 1 * scale);
  ctx.lineTo(R.x, R.y + 1 * scale);
  ctx.stroke();

  ctx.restore();

  // rim highlight
  ctx.save();
  ctx.strokeStyle = "rgba(201,211,160,.45)";
  ctx.lineWidth = Math.max(1, 1.1 * scale);
  ctx.beginPath();
  ctx.moveTo(L.x, L.y);
  ctx.lineTo(T.x, T.y);
  ctx.lineTo(R.x, R.y);
  ctx.stroke();
  ctx.restore();

  // a crooked welcome sign at the left edge
  const signP = iso(view, -0.25, 3.9);
  drawSign(ctx, view, signP.x, signP.y, Math.max(0.65, scale));

  // two foreground clumps of fern soften the bottom corners
  ctx.save();
  const f1 = iso(view, 7.15, 5.7);
  fern(ctx, f1.x, f1.y, scale * 1.5, seeded(33), "#678455");
  const f2 = iso(view, 0.15, 5.4);
  fern(ctx, f2.x, f2.y, scale * 1.3, seeded(34), "#718e5e");
  ctx.restore();

  // fireflies waiting in the grass
  ctx.save();
  for (let i = 0; i < 7; i++) {
    const p = iso(view, 0.2 + rnd() * (COLS - 0.5), 0.2 + rnd() * (ROWS - 0.5));
    drawSparkle(ctx, p.x, p.y - 4 * scale, (1.5 + rnd() * 1.8) * scale, "#f7df99", 0.35 + rnd() * 0.3);
  }
  ctx.restore();
}

import {
  TAU, roundRect, softShadow, leafPath, drawSparkle, drawHeart, seeded
} from "./art-core.js";

const rnd = seeded(122507);

function shadow(ctx, rx = 38, ry = 10) {
  softShadow(ctx, 0, 2, rx, ry, 0.19);
  ctx.save();
  ctx.fillStyle = "rgba(62,79,49,.12)";
  ctx.beginPath();
  ctx.ellipse(0, 2, rx * 0.85, ry * 0.72, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function steam(ctx, t, x, y, count = 3, spread = 8, size = 3) {
  ctx.save();
  for (let i = 0; i < count; i++) {
    const p = (t * 0.18 + i / count) % 1;
    const xx = x + Math.sin(t * 0.7 + i * 2.1) * spread * p;
    const yy = y - p * 32;
    ctx.globalAlpha = (1 - p) * 0.28;
    ctx.fillStyle = "#f7f0d9";
    ctx.beginPath();
    ctx.arc(xx, yy, size * (0.7 + p * 1.4), 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function fire(ctx, t, x, y, scale = 1) {
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);
  const wobble = Math.sin(t * 8.2) * 0.08;
  // outer glow
  const g = ctx.createRadialGradient(0, -8, 0, 0, -8, 36);
  g.addColorStop(0, "rgba(255,198,101,.42)");
  g.addColorStop(0.5, "rgba(244,153,79,.15)");
  g.addColorStop(1, "rgba(244,153,79,0)");
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, -8, 36, 0, TAU);
  ctx.fill();
  // flame body
  const flame = (color, sx, sy, alpha) => {
    ctx.globalAlpha = alpha;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(-8 * sx, -4 * sy, -7 * sx, -15 * sy, -1.5 * sx, -20 * sy);
    ctx.bezierCurveTo(0.5 * sx, -25 * sy + wobble * 10, 4 * sx, -18 * sy, 5 * sx, -13 * sy);
    ctx.bezierCurveTo(9 * sx, -6 * sy, 6 * sx, -2 * sy, 0, 0);
    ctx.fill();
  };
  flame("#e96e4b", 1.05, 1.05, 0.95);
  flame("#f2a053", 0.8, 0.88, 0.9);
  flame("#f8d47d", 0.5, 0.65, 0.9);
  ctx.globalAlpha = 1;
  // floating sparks
  for (let i = 0; i < 3; i++) {
    const p = (t * 0.38 + i / 3) % 1;
    ctx.fillStyle = "#f4c167";
    ctx.globalAlpha = (1 - p) * 0.8;
    ctx.beginPath();
    ctx.arc(Math.sin(t * 2 + i * 4) * 7 * p, -12 - p * 32, 1.1 * (1 - p) + 0.4, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

export function drawCampfire(ctx, t) {
  shadow(ctx, 45, 12);
  // back tripod leg
  ctx.save();
  ctx.strokeStyle = "#61503c";
  ctx.lineWidth = 3.2;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(-6, -30);
  ctx.lineTo(2, -71);
  ctx.stroke();

  fire(ctx, t, 0, -3, 1.18);

  // stones
  const stoneCols = ["#949482", "#a5a18e", "#85897a", "#b0a58e", "#959783", "#8b8e7d"];
  for (let i = 0; i < 10; i++) {
    const a = (i / 10) * TAU;
    const sx = Math.cos(a) * 33;
    const sy = Math.sin(a) * 12 + 0.5;
    ctx.fillStyle = stoneCols[i % stoneCols.length];
    ctx.beginPath();
    ctx.ellipse(sx, sy, 6.2 + (i % 3), 4 + (i % 2), a * 0.3, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "rgba(238,231,203,.22)";
    ctx.beginPath();
    ctx.ellipse(sx - 1.5, sy - 1.2, 3.3, 1.8, a * 0.3, 0, TAU);
    ctx.fill();
  }

  // logs
  ctx.save();
  ctx.translate(-4, -4);
  ctx.rotate(-0.28);
  ctx.fillStyle = "#71533a";
  roundRect(ctx, -21, -3, 44, 7, 3.5);
  ctx.fill();
  ctx.strokeStyle = "rgba(223,191,141,.22)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-16, -1);
  ctx.lineTo(16, -1);
  ctx.stroke();
  ctx.restore();
  ctx.save();
  ctx.translate(5, -2);
  ctx.rotate(0.45);
  ctx.fillStyle = "#5e4734";
  roundRect(ctx, -17, -3, 36, 6, 3);
  ctx.fill();
  ctx.restore();

  // kettle tripod
  ctx.strokeStyle = "#5a4d39";
  ctx.lineWidth = 3.1;
  ctx.beginPath();
  ctx.moveTo(-31, 0);
  ctx.lineTo(2, -70);
  ctx.lineTo(32, 0);
  ctx.moveTo(0, -63);
  ctx.lineTo(0, -45);
  ctx.stroke();

  // kettle
  ctx.save();
  ctx.translate(0, -39);
  ctx.fillStyle = "#7d8c7e";
  ctx.beginPath();
  ctx.ellipse(0, 0, 15, 12, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#617467";
  ctx.beginPath();
  ctx.ellipse(0, -5, 13, 6.5, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = "#56675a";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(0, -8, 9, Math.PI * 1.08, Math.PI * 1.92);
  ctx.stroke();
  ctx.fillStyle = "#617467";
  ctx.beginPath();
  ctx.moveTo(11, -4);
  ctx.quadraticCurveTo(23, -6, 22, 2);
  ctx.quadraticCurveTo(17, 4, 12, 3);
  ctx.fill();
  ctx.fillStyle = "rgba(233,236,215,.4)";
  ctx.beginPath();
  ctx.ellipse(-4, -2, 4, 2.2, -0.5, 0, TAU);
  ctx.fill();
  ctx.restore();
  steam(ctx, t, -1, -54, 3, 9, 2.5);
  ctx.restore();
}

export function drawNest(ctx, t) {
  shadow(ctx, 48, 13);
  // back rim
  ctx.save();
  ctx.fillStyle = "#8e6b48";
  ctx.beginPath();
  ctx.ellipse(0, -9, 43, 19, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#aa8458";
  ctx.beginPath();
  ctx.ellipse(0, -12, 37, 15, 0, 0, TAU);
  ctx.fill();
  // cushion
  const cushion = ctx.createLinearGradient(0, -28, 0, -4);
  cushion.addColorStop(0, "#e7d5b6");
  cushion.addColorStop(1, "#d5bf9a");
  ctx.fillStyle = cushion;
  ctx.beginPath();
  ctx.ellipse(0, -13, 30, 12, 0, 0, TAU);
  ctx.fill();
  // patchwork blanket
  ctx.fillStyle = "#c38e83";
  ctx.beginPath();
  ctx.moveTo(-31, -11);
  ctx.quadraticCurveTo(-13, -31, 8, -22);
  ctx.quadraticCurveTo(20, -14, 32, -11);
  ctx.quadraticCurveTo(18, 4, 0, 1);
  ctx.quadraticCurveTo(-17, 3, -31, -11);
  ctx.fill();
  ctx.strokeStyle = "rgba(255,246,222,.45)";
  ctx.lineWidth = 1;
  ctx.setLineDash([3, 3]);
  ctx.beginPath();
  ctx.moveTo(-23, -12);
  ctx.quadraticCurveTo(0, -18, 25, -11);
  ctx.stroke();
  ctx.setLineDash([]);
  // stitches
  for (let i = 0; i < 4; i++) {
    ctx.fillStyle = "#f2e4c6";
    ctx.beginPath();
    ctx.arc(-16 + i * 10, -9 + Math.sin(i) * 2, 1, 0, TAU);
    ctx.fill();
  }
  // pillow
  ctx.fillStyle = "#eee1c8";
  ctx.beginPath();
  ctx.ellipse(-21, -22, 12, 7, -0.18, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = "rgba(147,123,91,.22)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(-21, -22, 9, 4.8, -0.18, 0, TAU);
  ctx.stroke();
  // plush mushroom
  ctx.fillStyle = "#d7a383";
  ctx.beginPath();
  ctx.ellipse(18, -20, 8, 5, 0.1, Math.PI, TAU);
  ctx.fill();
  ctx.fillStyle = "#f1e6cc";
  roundRect(ctx, 15.7, -20, 4.8, 9, 2.2);
  ctx.fill();
  ctx.fillStyle = "#fff7e5";
  ctx.beginPath();
  ctx.arc(15.5, -22, 1.1, 0, TAU);
  ctx.arc(21, -21.5, 0.9, 0, TAU);
  ctx.fill();
  // woven front
  ctx.strokeStyle = "#866242";
  ctx.lineWidth = 2.3;
  ctx.lineCap = "round";
  for (let i = 0; i < 8; i++) {
    const x = -34 + i * 9.7;
    ctx.beginPath();
    ctx.moveTo(x, -17);
    ctx.quadraticCurveTo(x + 3, -7, x + 1, 1);
    ctx.stroke();
  }
  ctx.strokeStyle = "rgba(209,175,124,.5)";
  ctx.lineWidth = 1.4;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.moveTo(-34, -13 + i * 4);
    ctx.quadraticCurveTo(0, -18 + i * 5, 34, -12 + i * 4);
    ctx.stroke();
  }
  // tiny hanging star above the nest
  ctx.strokeStyle = "rgba(93,79,55,.55)";
  ctx.lineWidth = 0.9;
  ctx.beginPath();
  ctx.moveTo(36, -38);
  ctx.quadraticCurveTo(33, -48, 35, -57);
  ctx.stroke();
  drawSparkle(ctx, 35, -59, 4.5, "#e9c778", 0.85);
  ctx.restore();
}

export function drawGarden(ctx, t) {
  shadow(ctx, 47, 13);
  ctx.save();
  // soil bed
  const wood = ctx.createLinearGradient(0, -29, 0, 2);
  wood.addColorStop(0, "#96724d");
  wood.addColorStop(1, "#74573e");
  ctx.fillStyle = wood;
  ctx.beginPath();
  ctx.moveTo(-39, -21);
  ctx.lineTo(39, -21);
  ctx.lineTo(34, 1);
  ctx.lineTo(-34, 1);
  ctx.closePath();
  ctx.fill();
  // top rim
  ctx.fillStyle = "#a17c54";
  ctx.beginPath();
  ctx.ellipse(0, -21, 40, 12, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#5d4a36";
  ctx.beginPath();
  ctx.ellipse(0, -21, 33, 8.5, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#6e6248";
  ctx.beginPath();
  ctx.ellipse(0, -21, 29, 7, 0, 0, TAU);
  ctx.fill();
  // planks
  ctx.strokeStyle = "rgba(70,49,34,.28)";
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(-35 + i * 18, -20);
    ctx.lineTo(-31 + i * 18, 1);
    ctx.stroke();
  }
  // little nails
  ctx.fillStyle = "rgba(219,196,155,.55)";
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.arc(-28 + i * 18.5, -16, 0.9, 0, TAU);
    ctx.fill();
  }
  // veggies
  const veg = [
    [-22, -25, 1.02, 0.2],
    [-6, -26, 0.86, 2.2],
    [11, -24, 1.06, 4.0],
    [25, -23, 0.8, 1.2]
  ];
  for (const [x, y, s, phase] of veg) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(s, s);
    ctx.rotate(Math.sin(t * 1.1 + phase) * 0.02);
    ctx.strokeStyle = "#5d7e4c";
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(-2, -7, 0, -14);
    ctx.stroke();
    ctx.fillStyle = "#73945a";
    leafPath(ctx, -4, -10, 7, 11, -0.8);
    ctx.fill();
    ctx.fillStyle = "#86a468";
    leafPath(ctx, 4, -11, 7, 11, 0.75);
    ctx.fill();
    ctx.fillStyle = "#678a55";
    leafPath(ctx, 0, -14, 6, 10, 0.1);
    ctx.fill();
    // carrot/beet peeking
    if (phase < 2) {
      ctx.fillStyle = "#d48a63";
      ctx.beginPath();
      ctx.ellipse(1, -4, 2.5, 4, 0.2, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }
  // tomato stake
  ctx.strokeStyle = "#8a704e";
  ctx.lineWidth = 1.8;
  ctx.beginPath();
  ctx.moveTo(18, -24);
  ctx.lineTo(17, -58);
  ctx.stroke();
  ctx.fillStyle = "#d16f63";
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.arc(17 + (i - 1) * 5, -39 - i * 4, 2.3, 0, TAU);
    ctx.fill();
  }
  // butterfly
  const bx = 28 + Math.sin(t * 0.8) * 10;
  const by = -62 + Math.cos(t * 1.1) * 6;
  ctx.fillStyle = "rgba(239,186,112,.9)";
  ctx.beginPath();
  ctx.ellipse(bx - 2.5, by, 3.5, 2, -0.5 + Math.sin(t * 9) * 0.4, 0, TAU);
  ctx.ellipse(bx + 2.5, by, 3.5, 2, 0.5 + Math.sin(t * 9) * 0.4, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = "rgba(77,68,48,.5)";
  ctx.lineWidth = 0.7;
  ctx.beginPath();
  ctx.moveTo(bx, by);
  ctx.lineTo(bx, by + 3);
  ctx.stroke();
  // tiny sign
  ctx.fillStyle = "#9b8157";
  ctx.fillRect(31, -23, 2, 18);
  roundRect(ctx, 24, -28, 16, 8, 1.5);
  ctx.fillStyle = "#e8d6af";
  ctx.fill();
  ctx.fillStyle = "#7d8e68";
  ctx.font = "600 4px Fredoka, sans-serif";
  ctx.textAlign = "center";
  ctx.fillText("SOUP", 32, -23);
  ctx.restore();
}

export function drawGlowbush(ctx, t) {
  shadow(ctx, 42, 12);
  ctx.save();
  // stems
  ctx.strokeStyle = "#6a7f4e";
  ctx.lineWidth = 2;
  ctx.lineCap = "round";
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.moveTo(-2, -1);
    ctx.quadraticCurveTo(-10 + i * 7, -22, -16 + i * 10, -43);
    ctx.stroke();
  }
  // bush body
  const greens = ["#748e5b", "#809a64", "#688654", "#8ba36e"];
  const puffs = [
    [-21, -28, 18], [2, -39, 22], [24, -28, 17],
    [-8, -25, 20], [14, -19, 19], [0, -50, 15]
  ];
  for (let i = 0; i < puffs.length; i++) {
    ctx.fillStyle = greens[i % greens.length];
    ctx.beginPath();
    ctx.arc(puffs[i][0], puffs[i][1], puffs[i][2], 0, TAU);
    ctx.fill();
  }
  // leaf highlights
  ctx.fillStyle = "rgba(178,197,133,.28)";
  for (let i = 0; i < 6; i++) {
    const p = puffs[i];
    ctx.beginPath();
    ctx.ellipse(p[0] - 4, p[1] - 6, p[2] * 0.5, p[2] * 0.3, -0.5, 0, TAU);
    ctx.fill();
  }
  // glowing berries
  const berries = [
    [-25, -37], [-10, -48], [8, -54], [21, -40], [30, -26], [-2, -32], [12, -25], [-18, -19]
  ];
  for (let i = 0; i < berries.length; i++) {
    const [x, y] = berries[i];
    const pulse = 0.86 + Math.sin(t * 2 + i * 1.7) * 0.14;
    const g = ctx.createRadialGradient(x, y, 0, x, y, 10);
    g.addColorStop(0, "rgba(255,214,118,.4)");
    g.addColorStop(1, "rgba(255,214,118,0)");
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(x, y, 10 * pulse, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "#efb65b";
    ctx.beginPath();
    ctx.arc(x, y, 3.2 * pulse, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "rgba(255,245,196,.9)";
    ctx.beginPath();
    ctx.arc(x - 1, y - 1, 1, 0, TAU);
    ctx.fill();
  }
  // tiny sparkles
  drawSparkle(ctx, 33, -49, 2.4, "#f6d886", 0.55 + 0.3 * Math.sin(t * 2.3));
  drawSparkle(ctx, -32, -20, 1.8, "#f6d886", 0.45);
  ctx.restore();
}

export function drawRainbarrel(ctx, t) {
  shadow(ctx, 39, 11);
  ctx.save();
  // bamboo stand
  ctx.strokeStyle = "#7c754f";
  ctx.lineWidth = 4;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(-25, -4);
  ctx.lineTo(-19, -31);
  ctx.moveTo(26, -4);
  ctx.lineTo(20, -31);
  ctx.stroke();
  // barrel
  const wood = ctx.createLinearGradient(-34, 0, 34, 0);
