  ctx.strokeStyle = "rgba(107,77,50,.45)";
  ctx.lineWidth = 1;
  for (let i = 0; i < 3; i++) {
    ctx.beginPath();
    ctx.ellipse(0, -34, 22 - i * 7, 8 - i * 2.5, 0, 0, TAU);
    ctx.stroke();
  }
  // moss on stump
  ctx.fillStyle = "#77935d";
  ctx.beginPath();
  ctx.ellipse(-21, -39, 12, 5, -0.1, 0, TAU);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(-29, -26, 7, 10, -0.4, 0, TAU);
  ctx.fill();
  // book stack
  const bookCols = ["#bd786b", "#7c9482", "#d4ac67", "#a3829f"];
  for (let i = 0; i < 4; i++) {
    ctx.save();
    ctx.translate(-33 + (i % 2) * 1.5, -2 - i * 4.4);
    ctx.rotate(i % 2 ? 0.06 : -0.03);
    ctx.fillStyle = bookCols[i];
    roundRect(ctx, -12, -4, 24, 4.3, 1);
    ctx.fill();
    ctx.fillStyle = "rgba(244,234,205,.45)";
    ctx.fillRect(-8, -3.1, 14, 1);
    ctx.restore();
  }
  // lantern on right
  ctx.strokeStyle = "#676c58";
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(22, -36);
  ctx.lineTo(22, -45);
  ctx.stroke();
  ctx.fillStyle = "#6f806d";
  roundRect(ctx, 16, -54, 12, 10, 2);
  ctx.fill();
  ctx.fillStyle = "rgba(247,213,131,.85)";
  roundRect(ctx, 18, -52, 8, 6, 1);
  ctx.fill();
  const g = ctx.createRadialGradient(22, -49, 0, 22, -49, 25);
  g.addColorStop(0, "rgba(247,204,111,.3)");
  g.addColorStop(1, "rgba(247,204,111,0)");
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(22, -49, 25, 0, TAU);
  ctx.fill();
  // cup on stump
  ctx.fillStyle = "#e6d6b8";
  ctx.beginPath();
  ctx.ellipse(-3, -40, 5.5, 2.4, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#99745b";
  ctx.beginPath();
  ctx.ellipse(-3, -41, 4.2, 1.7, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = "#e6d6b8";
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.arc(3, -41, 3, -0.6, 1.5);
  ctx.stroke();
  // tiny mushroom by books
  ctx.fillStyle = "#e8dcc0";
  ctx.fillRect(-41, -10, 2.4, 8);
  ctx.fillStyle = "#d1907f";
  ctx.beginPath();
  ctx.ellipse(-39.8, -10, 5, 3, 0, Math.PI, TAU);
  ctx.fill();
  steam(ctx, t, -3, -44, 2, 4, 1.7);
  // open book floating? small sparkle
  drawSparkle(ctx, 28, -64, 2.4, "#f2d180", 0.6 + Math.sin(t * 1.8) * 0.2);
  ctx.restore();
}

export function drawSpa(ctx, t) {
  shadow(ctx, 49, 14);
  ctx.save();
  // stone ring
  const stones = ["#8f9382", "#9fa18d", "#7e8779", "#afaa92", "#939c8e", "#858c78"];
  for (let i = 0; i < 12; i++) {
    const a = (i / 12) * TAU;
    const sx = Math.cos(a) * 38;
    const sy = Math.sin(a) * 14;
    ctx.fillStyle = stones[i % stones.length];
    ctx.beginPath();
    ctx.ellipse(sx, sy - 3, 8.6, 6, a * 0.2, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "rgba(229,224,196,.16)";
    ctx.beginPath();
    ctx.ellipse(sx - 2, sy - 5, 4, 2.2, a * 0.2, 0, TAU);
    ctx.fill();
  }
  // pool water
  const water = ctx.createRadialGradient(-7, -12, 2, 0, -8, 35);
  water.addColorStop(0, "#a9d3c5");
  water.addColorStop(0.55, "#7fbcb3");
  water.addColorStop(1, "#63a49f");
  ctx.fillStyle = water;
  ctx.beginPath();
  ctx.ellipse(0, -8, 32, 12.5, 0, 0, TAU);
  ctx.fill();
  // ripples
  ctx.strokeStyle = "rgba(232,245,220,.42)";
  ctx.lineWidth = 0.8;
  for (let i = 0; i < 3; i++) {
    const rr = 5 + ((t * 5 + i * 11) % 24);
    ctx.globalAlpha = (1 - rr / 30) * 0.5;
    ctx.beginPath();
    ctx.ellipse(-3, -10, rr, rr * 0.34, 0, 0, TAU);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
  // foam
  ctx.fillStyle = "rgba(237,244,219,.35)";
  ctx.beginPath();
  ctx.ellipse(15, -6, 5, 1.3, 0.2, 0, TAU);
  ctx.fill();
  // bamboo
  ctx.strokeStyle = "#7a8c56";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(34, -38);
  ctx.quadraticCurveTo(34, -22, 40, -3);
  ctx.moveTo(34, -30);
  ctx.lineTo(29, -36);
  ctx.stroke();
  ctx.fillStyle = "#79975c";
  for (let i = 0; i < 3; i++) {
    leafPath(ctx, 37 + i * 2, -35 + i * 5, 6, 9, 0.8 + i * 0.2);
    ctx.fill();
  }
  // towel rock
  ctx.fillStyle = "#969685";
  ctx.beginPath();
  ctx.ellipse(-38, -5, 9, 7, -0.2, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#d6b8a0";
  roundRect(ctx, -44, -15, 14, 8, 3);
  ctx.fill();
  ctx.fillStyle = "rgba(255,246,222,.45)";
  ctx.fillRect(-43, -12, 10, 1.2);
  // steam
  steam(ctx, t, -10, -22, 4, 15, 3.8);
  steam(ctx, t + 2, 17, -18, 2, 7, 2.5);
  // little floating flowers
  ctx.fillStyle = "#efb8a8";
  for (let i = 0; i < 3; i++) {
    const a = i * 2.1 + t * 0.09;
    ctx.beginPath();
    ctx.arc(Math.cos(a) * 17, -10 + Math.sin(a) * 4, 1.7, 0, TAU);
    ctx.fill();
  }
  // lantern on right stone
  ctx.strokeStyle = "#6e715d";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(39, -25);
  ctx.lineTo(40, -32);
  ctx.stroke();
  ctx.fillStyle = "rgba(246,211,126,.85)";
  ctx.beginPath();
  ctx.arc(40, -33, 2.6, 0, TAU);
  ctx.fill();
  const g = ctx.createRadialGradient(40, -33, 0, 40, -33, 16);
  g.addColorStop(0, "rgba(246,211,126,.3)");
  g.addColorStop(1, "rgba(246,211,126,0)");
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(40, -33, 16, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function drawLantern(ctx, t) {
  shadow(ctx, 24, 8);
  ctx.save();
  // post
  ctx.strokeStyle = "#6f5c43";
  ctx.lineWidth = 4;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(-7, 0);
  ctx.quadraticCurveTo(-9, -33, -2, -55);
  ctx.quadraticCurveTo(2, -68, 14, -65);
  ctx.stroke();
  // hanging chain
  ctx.strokeStyle = "rgba(73,65,45,.75)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(14, -65);
  ctx.lineTo(15, -54);
  ctx.stroke();
  // glass lantern
  const g = ctx.createRadialGradient(16, -38, 0, 16, -38, 34);
  g.addColorStop(0, "rgba(248,208,120,.38)");
  g.addColorStop(1, "rgba(248,208,120,0)");
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(16, -38, 34, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#695f4c";
  ctx.beginPath();
  ctx.moveTo(9, -52);
  ctx.lineTo(22, -52);
  ctx.lineTo(24, -33);
  ctx.lineTo(7, -33);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = "rgba(250,213,133,.9)";
  ctx.beginPath();
  ctx.moveTo(11, -49);
  ctx.lineTo(20, -49);
  ctx.lineTo(21.5, -35);
  ctx.lineTo(9.5, -35);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = "#fff4c8";
  ctx.beginPath();
  ctx.ellipse(15, -42, 2.5, 4, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = "#665a47";
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(6, -52);
  ctx.lineTo(25, -52);
  ctx.stroke();
  // vines on the post
  ctx.strokeStyle = "#718c5c";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(-8, -4);
  ctx.bezierCurveTo(-15, -17, -3, -28, -8, -42);
  ctx.stroke();
  for (let i = 0; i < 4; i++) {
    ctx.fillStyle = "#7c9964";
    leafPath(ctx, -9 + Math.sin(i) * 3, -12 - i * 8, 4.5, 6.5, i % 2 ? 0.6 : -0.6);
    ctx.fill();
  }
  // small moth
  const mx = 31 + Math.sin(t * 0.9) * 8;
  const my = -27 + Math.cos(t * 1.3) * 5;
  ctx.fillStyle = "rgba(237,213,153,.8)";
  ctx.beginPath();
  ctx.ellipse(mx - 2, my, 2.7, 1.5, -0.4 + Math.sin(t * 10) * 0.3, 0, TAU);
  ctx.ellipse(mx + 2, my, 2.7, 1.5, 0.4 + Math.sin(t * 10) * 0.3, 0, TAU);
  ctx.fill();
  ctx.restore();
}

export function drawBuilding(ctx, type, t) {
  switch (type) {
    case "campfire": return drawCampfire(ctx, t);
    case "nest": return drawNest(ctx, t);
    case "garden": return drawGarden(ctx, t);
    case "glowbush": return drawGlowbush(ctx, t);
    case "rainbarrel": return drawRainbarrel(ctx, t);
    case "windchime": return drawWindchime(ctx, t);
    case "storystump": return drawStorystump(ctx, t);
    case "spa": return drawSpa(ctx, t);
    case "lantern": return drawLantern(ctx, t);
    default: return drawLantern(ctx, t);
  }
}

import { TAU, softShadow, leafPath, drawSparkle, drawHeart } from "./art-core.js";
import { PAL_SPECIES } from "./data.js";

function shadow(ctx, rx, ry) {
  softShadow(ctx, 0, 2, rx, ry, 0.19);
}

function expressionFor(p) {
  if (!p) return "happy";
  if (p.sleeping || p.energy < 16) return "sleepy";
  if (p.hunger < 30) return "hungry";
  if (p.joy < 30) return "sad";
  if (p.petting > 0) return "bliss";
  if (p.joy > 73) return "happy";
  return "neutral";
}

function isBlinking(p, t) {
  if (!p) return false;
  const cycle = 4.1 + (p.seed || 0) * 0.7;
  const bt = (t + (p.seed || 0) * 2.6) % cycle;
  return bt < 0.135 || (bt > 0.31 && bt < 0.39);
}

function eye(ctx, x, y, rx, ry, p, t, opts = {}) {
  const exp = opts.exp || expressionFor(p);
  const blink = isBlinking(p, t);
  ctx.save();
  ctx.strokeStyle = "#45503f";
  ctx.fillStyle = "#45503f";
  ctx.lineCap = "round";
  if (blink || opts.closed) {
    ctx.lineWidth = 1.8;
    ctx.beginPath();
    ctx.arc(x, y - 1, rx * 0.95, 0.18, Math.PI - 0.18);
    ctx.stroke();
  } else if (exp === "bliss") {
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(x, y + 1, rx * 1.05, Math.PI + 0.32, TAU - 0.32);
    ctx.stroke();
  } else if (exp === "sleepy") {
    ctx.lineWidth = 1.9;
    ctx.beginPath();
    ctx.arc(x, y, rx * 1.1, 0.2, Math.PI - 0.2);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(x, y + 1.8, rx * 0.92, 0.08, Math.PI - 0.08);
    ctx.stroke();
  } else {
    const squash = exp === "sad" ? 0.84 : 1;
    ctx.beginPath();
    ctx.ellipse(x, y, rx, ry * squash, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "rgba(255,252,235,.96)";
    ctx.beginPath();
    ctx.arc(x - rx * 0.3, y - ry * 0.34, rx * 0.31, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "rgba(255,255,255,.6)";
    ctx.beginPath();
    ctx.arc(x + rx * 0.29, y + ry * 0.27, rx * 0.14, 0, TAU);
    ctx.fill();
    if (exp === "sad") {
      ctx.strokeStyle = "rgba(69,80,63,.55)";
      ctx.lineWidth = 1.1;
      ctx.beginPath();
      ctx.moveTo(x - rx * 1.15, y - ry * 1.34);
      ctx.quadraticCurveTo(x, y - ry * 1.65, x + rx * 1.15, y - ry * 1.28);
      ctx.stroke();
    }
  }
  ctx.restore();
}

function blush(ctx, x, y, rx, alpha = 0.5, color = "#e89a91") {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.ellipse(x, y, rx, rx * 0.55, 0.1, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function mouth(ctx, x, y, type, scale = 1) {
  ctx.save();
  ctx.strokeStyle = "#4b5544";
  ctx.fillStyle = "#5a4f47";
  ctx.lineWidth = 1.5;
  ctx.lineCap = "round";
  if (type === "sleepy") {
    ctx.beginPath();
    ctx.arc(x, y, 3 * scale, 0.15, Math.PI - 0.2);
    ctx.stroke();
  } else if (type === "hungry") {
    ctx.beginPath();
    ctx.ellipse(x, y + 1, 2.1 * scale, 2.7 * scale, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "#d88d86";
    ctx.beginPath();
    ctx.ellipse(x, y + 2, 1.2 * scale, 1.3 * scale, 0, 0, TAU);
    ctx.fill();
  } else if (type === "sad") {
    ctx.beginPath();
    ctx.arc(x, y + 3.2, 3 * scale, Math.PI + 0.35, TAU - 0.35);
    ctx.stroke();
  } else if (type === "happy" || type === "bliss") {
    ctx.beginPath();
    ctx.arc(x, y - 0.5, 3.5 * scale, 0.18, Math.PI - 0.18);
    ctx.stroke();
    if (type === "bliss") {
      ctx.fillStyle = "#e49a91";
      ctx.beginPath();
      ctx.ellipse(x, y + 2.3, 1.6 * scale, 1.1 * scale, 0, 0, TAU);
      ctx.fill();
    }
  } else {
    ctx.beginPath();
    ctx.arc(x, y, 2.5 * scale, 0.28, Math.PI - 0.28);
    ctx.stroke();
  }
  ctx.restore();
}

function feet(ctx, y = -3, spread = 14, color = "rgba(95,79,62,.25)") {
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.ellipse(-spread, y, 8, 3.4, -0.08, 0, TAU);
  ctx.ellipse(spread, y, 8, 3.4, 0.08, 0, TAU);
  ctx.fill();
}

/* ------------------------------------------------------------------ */
/* Mallow — moss bun                                                   */
/* ------------------------------------------------------------------ */
function drawMallow(ctx, t, p, opts) {
  const seed = p?.seed || 0.5;
  const exp = opts.exp || expressionFor(p);
  const bob = Math.sin(t * 1.75 + seed * 6) * 1.9 + (p?.hop || 0);
  const tilt = Math.sin(t * 0.7 + seed * 5) * 0.025;
  shadow(ctx, 38, 10.5);
  ctx.save();
  ctx.translate(0, bob);
  ctx.rotate(tilt);

  // tail
  ctx.fillStyle = "#ead5b6";
  ctx.beginPath();
  ctx.arc(31, -15, 8.5, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "rgba(255,248,229,.5)";
  ctx.beginPath();
  ctx.arc(33, -17.5, 4, 0, TAU);
  ctx.fill();

  // ears
  const earGrad = ctx.createLinearGradient(-35, -110, 0, -60);
  earGrad.addColorStop(0, "#e9d2b2");
  earGrad.addColorStop(1, "#f4e3c7");
  ctx.fillStyle = earGrad;
  ctx.beginPath();
  ctx.moveTo(-19, -58);
  ctx.bezierCurveTo(-38, -73, -43, -107, -28, -113);
  ctx.bezierCurveTo(-15, -118, -8, -89, -13, -61);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(19, -58);
  ctx.bezierCurveTo(40, -76, 44, -106, 29, -110);
  ctx.bezierCurveTo(16, -113, 8, -87, 13, -61);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = "rgba(225,163,157,.55)";
  ctx.beginPath();
  ctx.moveTo(-19, -66);
  ctx.bezierCurveTo(-30, -79, -32, -101, -25, -104);
  ctx.bezierCurveTo(-18, -107, -14, -84, -15, -67);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(19, -66);
  ctx.bezierCurveTo(31, -80, 33, -100, 26, -103);
  ctx.bezierCurveTo(19, -105, 13, -83, 14, -67);
  ctx.closePath();
  ctx.fill();

  feet(ctx, -3.5, 14, "rgba(112,91,71,.27)");

  // body
  const body = ctx.createLinearGradient(-30, -76, 28, -2);
  body.addColorStop(0, "#f6e6cb");
  body.addColorStop(0.55, "#efdcbe");
  body.addColorStop(1, "#e3cbaa");
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.moveTo(-30, -35);
  ctx.bezierCurveTo(-36, -63, -22, -77, 0, -77);
  ctx.bezierCurveTo(22, -77, 36, -63, 32, -34);
  ctx.bezierCurveTo(30, -11, 17, -3, 0, -3);
  ctx.bezierCurveTo(-17, -3, -32, -12, -30, -35);
  ctx.fill();
  ctx.strokeStyle = "rgba(112,91,68,.13)";
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // belly
  ctx.fillStyle = "rgba(255,249,231,.64)";
  ctx.beginPath();
  ctx.ellipse(0, -26, 19, 22, 0, 0, TAU);
  ctx.fill();

  // arms
  ctx.fillStyle = "#ead5b6";
  ctx.beginPath();
  ctx.ellipse(-29, -30, 6.8, 11, 0.55, 0, TAU);
  ctx.ellipse(29, -30, 6.8, 11, -0.55, 0, TAU);
  ctx.fill();

  // face
  eye(ctx, -12.5, -49, 4.7, 6.6, p, t, { exp });
  eye(ctx, 12.5, -49, 4.7, 6.6, p, t, { exp });
  blush(ctx, -22.5, -37, 5.1, 0.55);
  blush(ctx, 22.5, -37, 5.1, 0.55);
  mouth(ctx, 0, -34, exp, 1);

  // sprout
  ctx.strokeStyle = "#698a51";
  ctx.lineWidth = 1.8;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(0, -76);
  ctx.quadraticCurveTo(-2, -86, 1, -91);
  ctx.stroke();
  ctx.fillStyle = "#71955a";
  leafPath(ctx, -4, -89, 8, 12, -0.7);
  ctx.fill();
  ctx.fillStyle = "#87a96b";
  leafPath(ctx, 5, -92, 7.5, 11, 0.8);
  ctx.fill();

  // flower at higher friendship
  if ((p?.level || 1) >= 3) {
    ctx.save();
    ctx.translate(24, -75);
    ctx.fillStyle = "#f6e7c4";
    for (let i = 0; i < 5; i++) {
      const a = (i / 5) * TAU;
      ctx.beginPath();
      ctx.ellipse(Math.cos(a) * 4, Math.sin(a) * 3.4, 3.2, 2.1, a, 0, TAU);
      ctx.fill();
    }
    ctx.fillStyle = "#e6b65b";
    ctx.beginPath();
    ctx.arc(0, 0, 2.1, 0, TAU);
    ctx.fill();
    ctx.restore();
  }
  ctx.restore();
}

/* ------------------------------------------------------------------ */
/* Taro — cloud pup                                                    */
/* ------------------------------------------------------------------ */
function drawTaro(ctx, t, p, opts) {
  const seed = p?.seed || 0.5;
  const exp = opts.exp || expressionFor(p);
  const bob = Math.sin(t * 1.25 + seed * 5) * 2.6 + (p?.hop || 0);
  shadow(ctx, 40, 10);
  ctx.save();
  ctx.translate(0, bob);

  // wispy little wings
  ctx.fillStyle = "rgba(205,230,219,.75)";
  ctx.beginPath();
  ctx.ellipse(-32, -38, 14, 7, -0.4, 0, TAU);
  ctx.ellipse(32, -38, 14, 7, 0.4, 0, TAU);
  ctx.fill();

  // horns
  ctx.fillStyle = "#afcbbd";
  ctx.beginPath();
  ctx.moveTo(-21, -64);
  ctx.quadraticCurveTo(-27, -77, -18, -78);
  ctx.quadraticCurveTo(-13, -73, -12, -63);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(21, -64);
  ctx.quadraticCurveTo(27, -77, 18, -78);
  ctx.quadraticCurveTo(13, -73, 12, -63);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = "#e7d8bb";
  ctx.beginPath();
  ctx.arc(-18, -76, 2.4, 0, TAU);
  ctx.arc(18, -76, 2.4, 0, TAU);
  ctx.fill();

  // cloud body (overlapping soft puffs)
  const bodyGrad = ctx.createLinearGradient(0, -72, 0, -2);
  bodyGrad.addColorStop(0, "#dbeade");
  bodyGrad.addColorStop(0.62, "#c5dccf");
  bodyGrad.addColorStop(1, "#aecbbd");
  ctx.fillStyle = bodyGrad;
  const puffs = [
    [-25, -37, 20], [25, -37, 20], [-19, -55, 19], [20, -54, 18],
    [0, -60, 25], [0, -32, 28], [-8, -21, 18], [16, -22, 17]
  ];
  for (const [x, y, r] of puffs) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fill();
  }
  // soft highlight
  ctx.fillStyle = "rgba(255,255,244,.28)";
  ctx.beginPath();
  ctx.ellipse(-13, -57, 19, 12, -0.4, 0, TAU);
  ctx.fill();

  // little feet
  ctx.fillStyle = "#abc8ba";
  ctx.beginPath();
  ctx.ellipse(-15, -4, 8, 3.5, -0.1, 0, TAU);
  ctx.ellipse(15, -4, 8, 3.5, 0.1, 0, TAU);
  ctx.fill();

  // belly
  ctx.fillStyle = "rgba(238,242,221,.55)";
  ctx.beginPath();
  ctx.ellipse(0, -26, 14, 17, 0, 0, TAU);
  ctx.fill();
  // belly star
  ctx.save();
  ctx.translate(0, -26);
  ctx.globalAlpha = 0.85;
  drawSparkle(ctx, 0, 0, 4.1, "#e7c26c", 1);
  ctx.restore();

  // face
  eye(ctx, -13.5, -45, 4.6, 6.3, p, t, { exp });
  eye(ctx, 13.5, -45, 4.6, 6.3, p, t, { exp });
  blush(ctx, -23, -34, 4.6, 0.4, "#e8a89b");
  blush(ctx, 23, -34, 4.6, 0.4, "#e8a89b");
  mouth(ctx, 0, -32, exp, 0.95);

  // forehead curl
  ctx.strokeStyle = "#92b5a7";
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(1, -64);
  ctx.bezierCurveTo(7, -70, 10, -64, 6, -61);
  ctx.stroke();

  // little drifting motes
  for (let i = 0; i < 2; i++) {
    const a = t * 0.8 + i * 3.2 + seed;
    ctx.globalAlpha = 0.25 + 0.15 * Math.sin(a);
    ctx.fillStyle = "#f8efd4";
    ctx.beginPath();
    ctx.arc(Math.cos(a) * 35, -50 + Math.sin(a * 1.3) * 18, 1.5, 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
  ctx.restore();
}

/* ------------------------------------------------------------------ */
/* Juniper — petal hog                                                */
/* ------------------------------------------------------------------ */
function drawJuniper(ctx, t, p, opts) {
  const seed = p?.seed || 0.5;
  const exp = opts.exp || expressionFor(p);
  const bob = Math.sin(t * 1.95 + seed * 4) * 1.8 + (p?.hop || 0);
  const tilt = Math.sin(t * 0.9 + seed * 2) * 0.018;
  shadow(ctx, 41, 11);
  ctx.save();
  ctx.translate(0, bob);
  ctx.rotate(tilt);

  // petal spines
  const petalCols = ["#d68d77", "#e3a087", "#c97f70", "#e8ae93"];
  for (let i = 0; i < 11; i++) {
    const a = -Math.PI * 0.93 + (i / 10) * Math.PI * 0.86;
    const len = i === 5 ? 44 : 34 + (i % 3) * 4;
    const x = Math.cos(a) * 22;
    const y = -33 + Math.sin(a) * 24;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(a + Math.PI / 2);
    ctx.fillStyle = petalCols[i % petalCols.length];
    ctx.beginPath();
    ctx.ellipse(0, -len * 0.44, 7.5, len * 0.48, 0, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "rgba(248,220,188,.28)";
    ctx.beginPath();
    ctx.ellipse(-2, -len * 0.48, 2.8, len * 0.23, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  feet(ctx, -3, 16, "rgba(125,84,61,.3)");

  // body
  const bodyGrad = ctx.createLinearGradient(0, -65, 0, -2);
  bodyGrad.addColorStop(0, "#f2cba3");
  bodyGrad.addColorStop(0.6, "#ecc096");
  bodyGrad.addColorStop(1, "#dca77f");
  ctx.fillStyle = bodyGrad;
  ctx.beginPath();
  ctx.ellipse(0, -31, 31, 30, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = "rgba(120,83,60,.12)";
  ctx.lineWidth = 1.2;
  ctx.stroke();

  // tiny satchel
  ctx.strokeStyle = "#97704f";
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  ctx.moveTo(-23, -49);
  ctx.quadraticCurveTo(-6, -31, 19, -38);
  ctx.stroke();
  ctx.fillStyle = "#a97d58";
  ctx.beginPath();
  ctx.ellipse(23, -31, 7.5, 8.2, -0.2, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#866044";
  ctx.fillRect(20, -33, 6, 1.6);
  ctx.fillStyle = "#e3c477";
  ctx.beginPath();
  ctx.arc(23, -31, 1.4, 0, TAU);
  ctx.fill();

  // arms
  ctx.fillStyle = "#e7b98f";
  ctx.beginPath();
  ctx.ellipse(-29, -24, 6.5, 10, 0.55, 0, TAU);
  ctx.ellipse(28, -23, 6.5, 10, -0.55, 0, TAU);
  ctx.fill();

  // face
  eye(ctx, -13, -47, 4.8, 6.4, p, t, { exp });
  eye(ctx, 13, -47, 4.8, 6.4, p, t, { exp });
  blush(ctx, -23, -35, 5, 0.55, "#dc8e7f");
  blush(ctx, 23, -35, 5, 0.55, "#dc8e7f");
  // muzzle
  ctx.fillStyle = "rgba(250,231,197,.7)";
  ctx.beginPath();
  ctx.ellipse(0, -32, 13, 9, 0, 0, TAU);
  ctx.fill();
  // nose
  ctx.fillStyle = "#8f6453";
  ctx.beginPath();
  ctx.ellipse(0, -36, 2.2, 1.5, 0, 0, TAU);
  ctx.fill();
  mouth(ctx, 0, -34, exp, 0.9);

  // daisy
  ctx.save();
  ctx.translate(-18, -61);
  ctx.fillStyle = "#f7eacb";
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * TAU + 0.3;
    ctx.beginPath();
    ctx.ellipse(Math.cos(a) * 5, Math.sin(a) * 4.2, 3.5, 2.1, a, 0, TAU);
    ctx.fill();
  }
  ctx.fillStyle = "#e1b34f";
  ctx.beginPath();
  ctx.arc(0, 0, 2.1, 0, TAU);
  ctx.fill();
  ctx.restore();

  ctx.restore();
}

/* ------------------------------------------------------------------ */
/* Bramble — mushroom cat                                             */
/* ------------------------------------------------------------------ */
function drawBramble(ctx, t, p, opts) {
  const seed = p?.seed || 0.5;
  const exp = opts.exp || expressionFor(p);
  const bob = Math.sin(t * 1.6 + seed * 4) * 1.7 + (p?.hop || 0);
  shadow(ctx, 37, 10);
  ctx.save();
  ctx.translate(0, bob);

  // tail
  ctx.strokeStyle = "#b49ec3";
  ctx.lineWidth = 8;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(24, -18);
  ctx.bezierCurveTo(48, -18, 44, -45, 55, -39);
  ctx.stroke();
  ctx.strokeStyle = "rgba(239,217,211,.35)";
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(31, -20);
  ctx.quadraticCurveTo(43, -31, 50, -37);
  ctx.stroke();

  // cat ears
  ctx.fillStyle = "#bda5cc";
  ctx.beginPath();
  ctx.moveTo(-25, -56);
  ctx.lineTo(-31, -76);
  ctx.lineTo(-12, -64);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(25, -56);
  ctx.lineTo(31, -76);
  ctx.lineTo(12, -64);
  ctx.closePath();
  ctx.fill();

  // body
  const body = ctx.createLinearGradient(0, -65, 0, -2);
  body.addColorStop(0, "#d7c5df");
  body.addColorStop(1, "#bca6ce");
  ctx.fillStyle = body;
  ctx.beginPath();
  ctx.ellipse(0, -31, 29, 32, 0, 0, TAU);
  ctx.fill();
  feet(ctx, -4, 13, "rgba(91,72,101,.26)");

  // belly
  ctx.fillStyle = "rgba(243,235,226,.5)";
  ctx.beginPath();
  ctx.ellipse(0, -20, 15, 15, 0, 0, TAU);
  ctx.fill();

  // mushroom cap
  const cap = ctx.createLinearGradient(0, -92, 0, -58);
  cap.addColorStop(0, "#b9819e");
  cap.addColorStop(0.65, "#a97190");
  cap.addColorStop(1, "#8f5f7c");
  ctx.fillStyle = cap;
  ctx.beginPath();
  ctx.moveTo(-37, -59);
  ctx.bezierCurveTo(-40, -86, -20, -96, 1, -96);
  ctx.bezierCurveTo(24, -96, 41, -85, 37, -59);
  ctx.quadraticCurveTo(0, -51, -37, -59);
  ctx.fill();
  ctx.fillStyle = "rgba(255,246,226,.85)";
  const spots = [[-21, -80, 4.2], [-5, -87, 3.2], [16, -83, 5], [28, -70, 2.5], [-32, -66, 2.4], [7, -74, 2.1]];
  for (const [x, y, r] of spots) {
    ctx.beginPath();
    ctx.ellipse(x, y, r, r * 0.7, 0.2, 0, TAU);
    ctx.fill();
  }
  // cap underside
  ctx.fillStyle = "#e3cfc2";
  ctx.beginPath();
  ctx.ellipse(0, -59, 34, 6, 0, 0, Math.PI);
  ctx.fill();
  ctx.strokeStyle = "rgba(105,78,91,.2)";
  ctx.lineWidth = 0.8;
  for (let i = 0; i < 7; i++) {
    ctx.beginPath();
    ctx.moveTo(-27 + i * 9, -58);
    ctx.lineTo(-25 + i * 8.5, -53);
    ctx.stroke();
  }

  // face
  eye(ctx, -12, -40, 4.7, 6.4, p, t, { exp });
  eye(ctx, 12, -40, 4.7, 6.4, p, t, { exp });
  blush(ctx, -21, -29, 4.7, 0.45, "#d8959c");
  blush(ctx, 21, -29, 4.7, 0.45, "#d8959c");
  // little fangs
  ctx.fillStyle = "#fbf2df";
  ctx.beginPath();
  ctx.moveTo(-4, -20);
  ctx.lineTo(-2.2, -17);
  ctx.lineTo(-0.8, -20);
  ctx.closePath();
  ctx.fill();
  mouth(ctx, 0, -26, exp, 0.9);

  // paws hugging a leaf
  ctx.fillStyle = "#cbb7d5";
  ctx.beginPath();
  ctx.ellipse(-16, -5, 7, 4.5, 0.2, 0, TAU);
  ctx.ellipse(16, -5, 7, 4.5, -0.2, 0, TAU);
  ctx.fill();
  ctx.fillStyle = "#7d9a64";
  leafPath(ctx, 0, -9, 8, 12, 0.2);
  ctx.fill();
  ctx.restore();
}

/* ------------------------------------------------------------------ */
/* Nimbus — mist drake                                                */
/* ------------------------------------------------------------------ */
function drawNimbus(ctx, t, p, opts) {
  const seed = p?.seed || 0.5;
  const exp = opts.exp || expressionFor(p);
  const bob = Math.sin(t * 1.45 + seed * 4) * 2.3 + (p?.hop || 0);
  shadow(ctx, 39, 10);
  ctx.save();
  ctx.translate(0, bob);

  // wings
  ctx.fillStyle = "rgba(174,211,215,.68)";
  ctx.beginPath();
  ctx.moveTo(-24, -45);
  ctx.bezierCurveTo(-55, -72, -63, -43, -43, -25);
  ctx.bezierCurveTo(-50, -44, -36, -49, -24, -45);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(24, -45);
  ctx.bezierCurveTo(55, -72, 63, -43, 43, -25);
  ctx.bezierCurveTo(50, -44, 36, -49, 24, -45);
  ctx.fill();
  ctx.strokeStyle = "rgba(115,162,168,.35)";
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(-28, -44);
  ctx.lineTo(-50, -43);
  ctx.moveTo(28, -44);
  ctx.lineTo(50, -43);
  ctx.stroke();

  // tail
  ctx.strokeStyle = "#a9cdd0";
  ctx.lineWidth = 7;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.moveTo(22, -18);
  ctx.bezierCurveTo(42, -12, 47, -28, 38, -35);
  ctx.stroke();
  drawSparkle(ctx, 38, -37, 4, "#e8c569", 0.9);

  // horns
  ctx.fillStyle = "#e7dcbf";
  ctx.beginPath();
  ctx.moveTo(-19, -68);
  ctx.quadraticCurveTo(-31, -79, -16, -82);
  ctx.quadraticCurveTo(-11, -76, -10, -65);
  ctx.closePath();
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(19, -68);
  ctx.quadraticCurveTo(31, -79, 16, -82);
  ctx.quadraticCurveTo(11, -76, 10, -65);
  ctx.closePath();
  ctx.fill();

  // cloud body
  const body = ctx.createLinearGradient(0, -74, 0, -2);
  body.addColorStop(0, "#d7e9e9");
  body.addColorStop(1, "#a8c9cd");
  ctx.fillStyle = body;
  const puffs = [
    [-22, -42, 20], [22, -42, 20], [0, -60, 27], [0, -29, 29],
    [-12, -67, 15], [13, -65, 16], [-17, -20, 18], [15, -20, 18]
  ];
  for (const [x, y, r] of puffs) {
    ctx.beginPath();
    ctx.arc(x, y, r, 0, TAU);
    ctx.fill();
  }
  ctx.fillStyle = "rgba(255,255,246,.25)";
  ctx.beginPath();
  ctx.ellipse(-10, -59, 17, 11, -0.4, 0, TAU);
  ctx.fill();

  // belly
  ctx.fillStyle = "rgba(238,244,228,.55)";
  ctx.beginPath();
  ctx.ellipse(0, -25, 15, 18, 0, 0, TAU);
  ctx.fill();
  drawSparkle(ctx, 0, -26, 4.5, "#e8c365", 0.9);

  // feet
  ctx.fillStyle = "#9fc4c8";
  ctx.beginPath();
  ctx.ellipse(-14, -3, 8, 3.3, -0.1, 0, TAU);
  ctx.ellipse(14, -3, 8, 3.3, 0.1, 0, TAU);
  ctx.fill();

  // face
  eye(ctx, -13, -46, 4.7, 6.5, p, t, { exp });
  eye(ctx, 13, -46, 4.7, 6.5, p, t, { exp });
  blush(ctx, -22, -34, 4.8, 0.42, "#df9c9d");
  blush(ctx, 22, -34, 4.8, 0.42, "#df9c9d");
  mouth(ctx, 0, -32, exp, 0.95);

  // cheek sparkle scales
  ctx.fillStyle = "rgba(246,233,194,.6)";
  ctx.beginPath();
  ctx.arc(-25, -46, 1.2, 0, TAU);
  ctx.arc(25, -46, 1.2, 0, TAU);
  ctx.fill();
  ctx.restore();
}

/* ------------------------------------------------------------------ */
/* Yuzu — dew snail                                                   */
/* ------------------------------------------------------------------ */
function drawYuzu(ctx, t, p, opts) {
  const seed = p?.seed || 0.5;
  const exp = opts.exp || expressionFor(p);
  const bob = Math.sin(t * 1.15 + seed * 4) * 1.4 + (p?.hop || 0);
  shadow(ctx, 47, 11);
  ctx.save();
  ctx.translate(0, bob);

  // foot
  const foot = ctx.createLinearGradient(0, -16, 0, 1);
  foot.addColorStop(0, "#efd594");
  foot.addColorStop(1, "#d6b16f");
  ctx.fillStyle = foot;
  ctx.beginPath();
  ctx.moveTo(-48, -4);
  ctx.quadraticCurveTo(-45, -14, -30, -13);
  ctx.lineTo(30, -13);
  ctx.quadraticCurveTo(44, -12, 45, -5);
  ctx.quadraticCurveTo(42, 2, 28, 2);
  ctx.lineTo(-32, 2);
  ctx.quadraticCurveTo(-48, 3, -48, -4);
  ctx.fill();
  // foot ruffle
  ctx.fillStyle = "#e7c584";
  for (let i = 0; i < 8; i++) {
    ctx.beginPath();
    ctx.ellipse(-37 + i * 10.5, 0.5, 5.5, 2.1, 0, 0, TAU);
    ctx.fill();
  }

  // shell
  const shell = ctx.createRadialGradient(-6, -45, 4, 3, -33, 36);
  shell.addColorStop(0, "#e5bf8c");
  shell.addColorStop(1, "#bc8d65");
  ctx.fillStyle = shell;
  ctx.beginPath();
  ctx.ellipse(7, -38, 32, 34, 0.05, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = "#a97c5c";
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.ellipse(7, -38, 29, 31, 0.05, 0, TAU);
  ctx.stroke();
  // spiral
  ctx.strokeStyle = "rgba(121,84,60,.62)";
  ctx.lineWidth = 2.2;
  ctx.beginPath();
  for (let a = 0; a < TAU * 2.4; a += 0.18) {
    const rr = 2 + a * 2.6;
    const x = 5 + Math.cos(a + 1.2) * rr;
    const y = -40 + Math.sin(a + 1.2) * rr * 0.9;
    if (a === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.stroke();
  ctx.strokeStyle = "rgba(251,234,194,.3)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(1, -47, 13, 10, -0.5, 0.2, 3);
  ctx.stroke();
  // tiny garden on shell
  ctx.strokeStyle = "#6f8c53";
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(12, -67);
  ctx.quadraticCurveTo(15, -75, 12, -79);
  ctx.moveTo(3, -63);
  ctx.quadraticCurveTo(1, -71, 5, -74);
  ctx.stroke();
  ctx.fillStyle = "#7e9b5f";
  leafPath(ctx, 11, -76, 5, 7, 0.2);
  ctx.fill();
  leafPath(ctx, 4, -72, 4.5, 6, -0.6);
  ctx.fill();
  ctx.fillStyle = "#e4a282";
  ctx.beginPath();
  ctx.arc(12, -80, 2.2, 0, TAU);
  ctx.fill();

  // neck / head
  const neck = ctx.createLinearGradient(-40, -40, -25, -4);
  neck.addColorStop(0, "#f2d999");
  neck.addColorStop(1, "#e0bb79");
  ctx.fillStyle = neck;
  ctx.beginPath();
  ctx.moveTo(-31, -9);
  ctx.bezierCurveTo(-43, -20, -45, -35, -38, -45);
  ctx.bezierCurveTo(-31, -54, -18, -49, -17, -37);
  ctx.lineTo(-18, -10);
  ctx.closePath();
  ctx.fill();

  // eyestalks
  ctx.strokeStyle = "#e7c585";
  ctx.lineWidth = 2.7;
  ctx.lineCap = "round";
  const sway = Math.sin(t * 1.1 + seed) * 2.5;
  ctx.beginPath();
  ctx.moveTo(-35, -45);
  ctx.quadraticCurveTo(-41 + sway, -56, -43 + sway, -60);
  ctx.moveTo(-27, -46);
  ctx.quadraticCurveTo(-25 - sway, -57, -26 - sway, -62);
  ctx.stroke();
  // eyes at stalk tips
  ctx.fillStyle = "#f5dfaa";
  ctx.beginPath();
  ctx.arc(-43 + sway, -61, 4.8, 0, TAU);
  ctx.arc(-26 - sway, -63, 4.8, 0, TAU);
  ctx.fill();
  // pupils
  eye(ctx, -43 + sway, -61, 2.3, 3.3, p, t, { exp: exp === "sleepy" ? "sleepy" : "neutral" });
  eye(ctx, -26 - sway, -63, 2.3, 3.3, p, t, { exp: exp === "sleepy" ? "sleepy" : "neutral" });

  // face on head
  blush(ctx, -37, -34, 3.8, 0.45, "#dd9c84");
  mouth(ctx, -34, -29, exp === "sleepy" ? "sleepy" : exp, 0.8);

  // dew bead
  ctx.fillStyle = "rgba(148,207,196,.8)";
  ctx.beginPath();
  ctx.ellipse(-45, -19, 1.8, 3, 0.2, 0, TAU);
  ctx.fill();
  ctx.restore();
}

const DRAWERS = {
  mallow: drawMallow,
  taro: drawTaro,
  juniper: drawJuniper,
  bramble: drawBramble,
  nimbus: drawNimbus,
  yuzu: drawYuzu
};

export function drawPal(ctx, species, t, pal, opts = {}) {
  const fn = DRAWERS[species] || drawMallow;
  fn(ctx, t, pal, opts);
}

export function drawCollectible(ctx, res, t, scale = 1) {
  ctx.save();
  ctx.scale(scale, scale);
  const bob = Math.sin(t * 3.1 + (res === "berries" ? 1 : res === "sparks" ? 2 : 0)) * 2.4;
  // glow
  const color = res === "dew" ? "rgba(111,189,183,.35)" : res === "berries" ? "rgba(217,111,105,.3)" : "rgba(244,196,95,.4)";
  const g = ctx.createRadialGradient(0, bob, 0, 0, bob, 18);
  g.addColorStop(0, color);
  g.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, bob, 18, 0, TAU);
  ctx.fill();
  // little shadow
  ctx.fillStyle = "rgba(63,82,48,.15)";
  ctx.beginPath();
  ctx.ellipse(0, 7, 7, 2.4, 0, 0, TAU);
  ctx.fill();
  ctx.translate(0, bob);
  if (res === "dew") {
    ctx.fillStyle = "#69aaa4";
    ctx.beginPath();
    ctx.moveTo(0, -10);
    ctx.bezierCurveTo(-7, -2, -5.8, 5, 0, 6);
    ctx.bezierCurveTo(5.8, 5, 7, -2, 0, -10);
    ctx.fill();
    ctx.fillStyle = "rgba(255,255,255,.65)";
    ctx.beginPath();
    ctx.ellipse(-1.8, 0, 1.4, 2.4, -0.3, 0, TAU);
    ctx.fill();
  } else if (res === "berries") {
    ctx.fillStyle = "#d96f69";
    ctx.beginPath();
    ctx.arc(-3.5, 1, 4.2, 0, TAU);
    ctx.arc(3.3, 2.2, 3.8, 0, TAU);
    ctx.arc(0, -3.8, 4, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "rgba(255,255,255,.45)";
    ctx.beginPath();
    ctx.arc(-4.6, -0.2, 1.1, 0, TAU);
    ctx.fill();
    ctx.fillStyle = "#658254";
    leafPath(ctx, 1, -8, 4, 4.5, 0.6);
    ctx.fill();
  } else {
    ctx.fillStyle = "#efc25f";
    ctx.beginPath();
    ctx.moveTo(0, -10);
    ctx.lineTo(2.5, -3);
    ctx.lineTo(10, 0);
    ctx.lineTo(2.5, 3);
    ctx.lineTo(0, 10);
    ctx.lineTo(-2.5, 3);
    ctx.lineTo(-10, 0);
    ctx.lineTo(-2.5, -3);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = "rgba(255,247,208,.7)";
    ctx.beginPath();
    ctx.arc(-1.5, -2, 1.7, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

export function drawPalPortrait(ctx, species, pal, t, size = 200) {
  ctx.clearRect(0, 0, size, size);
  ctx.save();
  ctx.translate(size * 0.5, size * 0.84);
  ctx.scale(size / 175, size / 175);
  // little hill
  const hill = ctx.createRadialGradient(0, 0, 4, 0, 0, 55);
  hill.addColorStop(0, "rgba(151,177,119,.34)");
  hill.addColorStop(1, "rgba(151,177,119,0)");
  ctx.fillStyle = hill;
  ctx.beginPath();
  ctx.ellipse(0, 0, 54, 16, 0, 0, TAU);
  ctx.fill();
  drawPal(ctx, species, t, pal, { exp: expressionFor(pal) });
  ctx.restore();
}

export class Soundscape {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = true;
    this.started = false;
    this.timer = null;
  }

  init() {
    if (this.ctx) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.enabled ? 0.22 : 0;
    this.master.connect(this.ctx.destination);
    this.started = true;
    this.startAmbient();
  }

  resume() {
    this.init();
    if (this.ctx?.state === "suspended") this.ctx.resume();
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(on ? 0.22 : 0, this.ctx.currentTime + 0.12);
    }
  }

  startAmbient() {
    if (!this.ctx || this.timer) return;
    const ctx = this.ctx;
    // A soft, slowly breathing pad.
    const padGain = ctx.createGain();
    padGain.gain.value = 0.024;
    padGain.connect(this.master);
    const filter = ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = 620;
    filter.Q.value = 0.4;
    filter.connect(padGain);
    const notes = [146.83, 220.0, 293.66, 369.99];
    notes.forEach((freq, i) => {
      const osc = ctx.createOscillator();
      osc.type = i % 2 ? "sine" : "triangle";
      osc.frequency.value = freq;
      const g = ctx.createGain();
      g.gain.value = i === 0 ? 0.12 : 0.055;
      const lfo = ctx.createOscillator();
      lfo.frequency.value = 0.035 + i * 0.011;
      const lfoGain = ctx.createGain();
      lfoGain.gain.value = 0.025;
      lfo.connect(lfoGain);
      lfoGain.connect(g.gain);
      osc.connect(g);
      g.connect(filter);
      osc.start();
      lfo.start();
    });
    // Occasional tiny pentatonic pluck, like a wind chime.
    const scale = [392, 440, 523.25, 587.33, 659.25, 783.99];
    const pluck = () => {
      if (!this.enabled || !this.ctx) return;
      const now = ctx.currentTime;
      const freq = scale[Math.floor(Math.random() * scale.length)];
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      const pan = ctx.createStereoPanner();
      osc.type = "sine";
      osc.frequency.value = freq;
      pan.pan.value = (Math.random() - 0.5) * 0.7;
      gain.gain.setValueAtTime(0, now);
      gain.gain.linearRampToValueAtTime(0.022, now + 0.015);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 1.8);
      osc.connect(gain);
      gain.connect(pan);
      pan.connect(this.master);
      osc.start(now);
      osc.stop(now + 1.9);
      this.timer = setTimeout(pluck, 2800 + Math.random() * 6000);
    };
    this.timer = setTimeout(pluck, 2400);
  }

  tone(freq, duration = 0.25, type = "sine", volume = 0.12, delay = 0) {
    if (!this.ctx || !this.enabled) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.linearRampToValueAtTime(volume, t + 0.012);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(t);
    osc.stop(t + duration + 0.02);
  }

  click() {
    this.tone(520, 0.09, "sine", 0.05);
    this.tone(780, 0.08, "sine", 0.025, 0.025);
  }

  collect() {
    this.tone(698, 0.16, "sine", 0.08);
    this.tone(1046, 0.24, "sine", 0.045, 0.045);
  }

  pet() {
    this.tone(440, 0.22, "sine", 0.07);
    this.tone(554, 0.3, "sine", 0.05, 0.08);
    this.tone(659, 0.35, "triangle", 0.025, 0.16);
  }

  feed() {
    this.tone(330, 0.1, "triangle", 0.07);
    this.tone(494, 0.18, "sine", 0.06, 0.07);
  }

  play() {
    this.tone(523, 0.11, "triangle", 0.06);
    this.tone(659, 0.11, "triangle", 0.05, 0.06);
    this.tone(784, 0.2, "triangle", 0.05, 0.12);
  }

  build() {
    this.tone(392, 0.13, "triangle", 0.07);
    this.tone(523, 0.16, "sine", 0.06, 0.06);
    this.tone(784, 0.25, "sine", 0.05, 0.14);
  }

  level() {
    const seq = [392, 493.88, 587.33, 783.99, 987.77];
    seq.forEach((f, i) => this.tone(f, 0.38, "sine", 0.07, i * 0.1));
  }

  quest() {
    this.tone(659, 0.18, "sine", 0.06);
    this.tone(880, 0.28, "sine", 0.05, 0.07);
  }

  error() {
    this.tone(220, 0.1, "sine", 0.04);
    this.tone(196, 0.14, "sine", 0.03, 0.07);
  }
}

