1708:   particles = particles.filter((p) => p.life < p.max);
1709: }
1710: 
1711: function updatePal(p, dt) {
1712:   p.petting = Math.max(0, p.petting - dt);
1713:   p.hop += (0 - p.hop) * Math.min(1, dt * 7);
1714:   p.screen = iso(view, p.x, p.y);
1715: 
1716:   const joyAura = state.buildings.filter((b) => BUILDING_TYPES[b.type].aura === "joy").length;
1717:   const restAura = state.buildings.filter((b) => BUILDING_TYPES[b.type].aura === "rest").length;
1718:   const snackAura = state.buildings.filter((b) => b.type === "garden").length;
1719: 
1720:   if (p.sleeping) {
1721:     p.energy = clamp(p.energy + dt * 4.2, 0, 100);
1722:     p.joy = clamp(p.joy - dt * 0.015, 0, 100);
1723:     if (p.energy > 68) {
1724:       p.sleeping = false;
1725:       p.idle = 0.5;
1726:     }
1727:     return;
1728:   }
1729: 
1730:   p.hunger = clamp(p.hunger - dt * (0.066 - snackAura * 0.008), 0, 100);
1731:   p.joy = clamp(p.joy - dt * (0.052 - joyAura * 0.006), 0, 100);
1732:   p.energy = clamp(p.energy - dt * (0.045 - restAura * 0.006), 0, 100);
1733:   if (p.hunger < 22) p.joy = clamp(p.joy - dt * 0.024, 0, 100);
1734:   if (p.energy < 9) {
1735:     p.sleeping = true;
1736:     p.moving = false;
1737:     p.hop = 0;
1738:   }
1739: 
1740:   if (p.moving) {
1741:     const dx = p.tx - p.x;
1742:     const dy = p.ty - p.y;
1743:     const dist = Math.hypot(dx, dy);
1744:     const speed = 0.58;
1745:     if (dist < 0.035) {
1746:       p.x = p.tx;
1747:       p.y = p.ty;
1748:       p.moving = false;
1749:       p.idle = rand(5.5, 2.1);
1750:     } else {
1751:       p.x += (dx / dist) * speed * dt;
1752:       p.y += (dy / dist) * speed * dt;
1753:     }
1754:   } else {
1755:     p.idle -= dt;
1756:     if (p.idle <= 0) {
1757:       const angle = Math.random() * TAU2;
1758:       const dist = rand(2.1, 0.8);
1759:       let c = p.x + Math.cos(angle) * dist;
1760:       let r = p.y + Math.sin(angle) * dist;
1761:       c = clamp(c, 0.45, COLS - 0.45);
1762:       r = clamp(r, 0.45, ROWS - 0.45);
1763:       if (occupied(Math.round(c), Math.round(r))) {
1764:         [c, r] = nextOpenTileNear(c, r, 2);
1765:         c += rand(0.25, -0.25);
1766:         r += rand(0.2, -0.2);
1767:       }
1768:       p.tx = clamp(c, 0.4, COLS - 0.4);
1769:       p.ty = clamp(r, 0.4, ROWS - 0.4);
1770:       p.moving = true;
1771:       p.idle = rand(5, 2.4);
1772:     }
1773:   }
1774: }
1775: 
1776: function updateGame(dt) {
1777:   gameTime += dt;
1778:   refreshScreenPositions();
1779:   for (const p of state.pals) updatePal(p, dt);
1780: 
1781:   // building production
1782:   for (const b of state.buildings) {
1783:     const data = BUILDING_TYPES[b.type];
1784:     if (data.produce && b.readyIn !== null) {
1785:       b.readyIn -= dt;
1786:       if (b.readyIn <= 0) {
1787:         b.readyIn += data.produce.interval;
1788:         buildingCollectible(b);
