    const lean = (rnd() - 0.5) * 10 * s;
    ctx.beginPath();
    ctx.moveTo(x + (i - 1) * 2 * s, y);
    ctx.quadraticCurveTo(x + lean, y - 6 * s, x + lean * 1.3, y - (6 + rnd() * 7) * s);
    ctx.stroke();
  }
  ctx.restore();
}

function flower(ctx, x, y, s, rnd, color) {
  ctx.save();
  ctx.strokeStyle = "#72915d";
  ctx.lineWidth = Math.max(0.7, 0.9 * s);
