  ctx.moveTo(x, y);
  ctx.quadraticCurveTo(x + 1.5 * s, y - 5 * s, x + (rnd() - 0.5) * 3 * s, y - 9 * s);
  ctx.stroke();
  const fy = y - 9.5 * s;
  const petal = 1.8 * s;
  ctx.fillStyle = color;
  for (let i = 0; i < 5; i++) {
    const a = (i / 5) * TAU + 0.3;
    ctx.beginPath();
    ctx.ellipse(x + Math.cos(a) * petal, fy + Math.sin(a) * petal * 0.75, petal * 0.85, petal * 0.55, a, 0, TAU);
