    ctx.ellipse(p.x, p.y, rx, ry, rnd(), 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  // faint builder grid
  ctx.strokeStyle = "rgba(60,81,51,.055)";
  ctx.lineWidth = 1;
