.panel-close:hover { background: rgba(88, 109, 78, .13); transform: rotate(4deg); }
.sheet-head .panel-close { position: absolute; right: 0; top: 2px; }
.sheet-foot {
  display: flex; align-items: center; justify-content: space-between; gap: 15px;
  margin-top: 13px; padding-top: 11px;
  border-top: 1px dashed rgba(86, 109, 74, .19);
  font-size: 10px; color: #899780;
}
.text-btn {
  display: inline-flex; align-items: center; gap: 4px;
  font-size: 11px; font-weight: 600; color: #4b6a4c;
  padding: 7px 4px;
}
.text-btn svg { width: 14px; height: 14px; }
.text-btn:hover { color: #2f4f38; }
.text-btn:hover svg { transform: translateX(2px); }
.text-btn svg { transition: transform .15s ease; }

/* build list */
.build-list {
  display: flex;
  gap: 9px;
  margin-top: 14px;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 2px 2px 7px;
  scrollbar-width: none;
  touch-action: pan-x;
}
.build-list::-webkit-scrollbar { display: none; }
.build-card {
  position: relative;
  flex: 1 0 128px;
  min-width: 118px;
  max-width: 155px;
  padding: 5px 9px 10px;
  border-radius: 18px;
  text-align: left;
  background: rgba(255, 252, 244, .65);
  border: 1px solid rgba(81, 105, 72, .12);
  transition: transform .18s ease, background .18s ease, box-shadow .18s ease, border-color .18s ease;
}
.build-card:hover { transform: translateY(-3px); background: #fffcf2; box-shadow: 0 9px 20px rgba(62, 83, 52, .11); }
.build-card.selected { background: #f6efd7; border-color: #b7a06a; box-shadow: 0 0 0 2px rgba(203, 169, 96, .25), 0 10px 20px rgba(62, 83, 52, .12); }
.build-card.unaffordable { opacity: .64; }
.build-card.unaffordable:hover { transform: none; }
.build-thumb { width: 100%; height: 72px; display: block; border-radius: 12px; background: linear-gradient(180deg, rgba(218,231,201,.68), rgba(233,238,212,.35)); }
.build-card h4 { margin: 7px 1px 1px; font-family: var(--display); font-size: 14px; line-height: 1; font-weight: 600; color: #38523b; }
.build-card p { margin: 4px 1px 0; font-size: 8px; line-height: 1.35; color: #84937a; min-height: 22px; }
.build-cost {
  display: inline-flex; align-items: center; gap: 2px;
  margin-top: 5px; padding: 2px 7px 2px 4px;
  border-radius: 999px;
  background: rgba(97, 161, 156, .11);
  color: #4b8b87;
  font-size: 10px; font-weight: 700;
}
.build-cost svg { width: 15px; height: 15px; }
.build-cost.short { background: rgba(210, 100, 95, .1); color: #b85e5b; }
.build-card .owned-tag {
  position: absolute; top: 8px; right: 9px;
  padding: 3px 6px; border-radius: 999px;
  background: rgba(253, 248, 235, .9);
  font-size: 7px; text-transform: uppercase; letter-spacing: .9px; color: #7f9273;
