import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ channel:'chromium', headless:true, args:['--enable-gpu','--ignore-gpu-blocklist','--use-angle=swiftshader'] });
const errors=[]; const page = await browser.newPage({ viewport:{width:390,height:844}, deviceScaleFactor:1, isMobile:true, hasTouch:true });
page.on('pageerror',e=>errors.push('PAGEERR '+e.message));
await page.goto('http://localhost:3000/', {waitUntil:'networkidle'}); await page.evaluate(()=>localStorage.clear());
await page.reload({waitUntil:'networkidle'}); await page.waitForTimeout(900);
// tap Mallow
const pos = await page.evaluate(()=>{const p=__mosslight.state.pals.find(p=>p.id==='mallow');const s=__mosslight.iso(__mosslight.view,p.x,p.y);return {x:s.x,y:s.y-60*__mosslight.view.scale};});
await page.touchscreen.tap(pos.x,pos.y); await page.waitForTimeout(500);
await page.screenshot({path:'/tmp/opencode/shots/m-panel.jpg',type:'jpeg',quality:74});
await page.locator('#palClose').click(); await page.waitForTimeout(300);
await page.locator('#buildBtn').click(); await page.waitForTimeout(600);
await page.screenshot({path:'/tmp/opencode/shots/m-build.jpg',type:'jpeg',quality:74});
await page.locator('#buildClose').click(); await page.waitForTimeout(250);
