input.content:
import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ channel:'chromium', headless:true, args:['--enable-gpu','--ignore-gpu-blocklist','--use-angle=swiftshader'] });
const errors=[];
const page = await browser.newPage({ viewport:{width:1280,height:800}, deviceScaleFactor:1 });
page.on('pageerror', e => errors.push('PAGEERROR: '+e.message));
page.on('console', m => { if(m.type()==='error') errors.push('CONSOLE: '+m.text()); });
await page.goto('http://localhost:3000/', {waitUntil:'networkidle'});
await page.evaluate(()=>localStorage.clear());
await page.reload({waitUntil:'networkidle'});
await page.waitForTimeout(1200);

const snap = async (label) => {
  await page.screenshot({path:`/tmp/opencode/shots/q-${label}.jpg`, type:'jpeg', quality:72});
};
const log = async (label) => {
  const s = await page.evaluate(()=>({
    q: __mosslight.state.questIndex, prog: __mosslight.state.questProgress,
    title: document.querySelector('#questTitle').textContent,
    step: document.querySelector('#questStep').textContent,
    warmth: Math.round(__mosslight.state.warmth), lvl: document.querySelector('#hearthLevel')?.textContent,
    dew: __mosslight.state.resources.dew, berries: __mosslight.state.resources.berries, sparks: __mosslight.state.resources.sparks,
    pals: __mosslight.state.pals.length,
    levelOpen: !document.querySelector('#levelUp').hidden,
    levelTitle: document.querySelector('#levelUpTitle').textContent,
    active: document.querySelector('#questCard').className
  }));
  console.log(label, JSON.stringify(s));
  return s;
};
const closeLevel = async () => {
  if (await page.locator('#levelUp').isVisible()) {
    await page.waitForTimeout(700);
    await snap('levelup');
    await page.locator('#levelUpBtn').click();
    await page.waitForTimeout(900);
    // close any queued level-up too
    if (await page.locator('#levelUp').isVisible()) {
      await page.locator('#levelUpBtn').click();
      await page.waitForTimeout(900);
    }
  }
};

await log('start');
// select Mallow
const pos = await page.evaluate(()=>{const p=__mosslight.state.pals.find(p=>p.species==='mallow');const s=__mosslight.iso(__mosslight.view,p.x,p.y);return {x:s.x,y:s.y-40*__mosslight.view.scale};});
await page.mouse.click(pos.x,pos.y);
await page.waitForTimeout(500);
console.log('panel visible', await page.locator('#palPanel').isVisible());

// quest 1: two pets
await page.locator('#petBtn').click();
await page.waitForTimeout(360);
await page.locator('#petBtn').click();
await page.waitForTimeout(900);
await log('after-pets');
await closeLevel();

// quest 2: two feeds
await page.locator('#feedBtn').click();
await page.waitForTimeout(500);
await page.locator('#feedBtn').click();
await page.waitForTimeout(1000);
await log('after-feeds');
await closeLevel();

// quest 3: build
await page.locator('#palClose').click();
await page.waitForTimeout(250);
await page.locator('#buildBtn').click();
await page.waitForTimeout(700);
await page.locator('.build-card[data-build="glowbush"]').click();
await page.waitForTimeout(500);
const spot = await page.evaluate(()=>__mosslight.iso(__mosslight.view, 6.4, 1.2));
await page.mouse.click(spot.x, spot.y - 10);
await page.waitForTimeout(900);
await log('after-build');
await closeLevel();

// quest 4: two plays
const pos2 = await page.evaluate(()=>{const p=__mosslight.state.pals.find(p=>p.species==='mallow');const s=__mosslight.iso(__mosslight.view,p.x,p.y);return {x:s.x,y:s.y-40*__mosslight.view.scale};});
await page.mouse.click(pos2.x,pos2.y);
await page.waitForTimeout(450);
await page.locator('#playBtn').click();
await page.waitForTimeout(500);
await page.locator('#playBtn').click();
await page.waitForTimeout(1300);
await log('after-plays');
await closeLevel();
await page.waitForTimeout(1200);
await log('after-pals-quests');
await closeLevel();
await snap('mid');

// quest 7: spawn and collect 8 treasures
await page.evaluate(()=>{
  const cols=['dew','berries','sparks'];
  const existing = __mosslight.collectibles.length;
  for (let i=0;i<8-existing;i++) {
    __mosslight.collectibles.push({id:'tst'+i, res:cols[i%3], c:0.7+(i%4)*0.55, r:1.2+Math.floor(i/4)*0.5, jx:0, jy:0, amount:1, phase:i, born:0, ttl:999});
  }
});
await page.waitForTimeout(400);
const spots = await page.evaluate(()=>__mosslight.collectibles.map(c=>{const b=__mosslight.iso(__mosslight.view,c.c,c.r);return {x:b.x,y:b.y-8*__mosslight.view.scale,id:c.id};}));
for (const sp of spots) {
  await page.mouse.click(sp.x, sp.y);
  await page.waitForTimeout(320);
}
await page.waitForTimeout(900);
await log('after-collect');
await closeLevel();
await page.waitForTimeout(1400);
const fin = await page.evaluate(()=>({title:document.querySelector('#questTitle').textContent, step:document.querySelector('#questStep').textContent, count:document.querySelector('#questCount').textContent, allDone:document.querySelector('#questStep').textContent.includes('all')||document.querySelector('#questStep').textContent.includes('done'), errs:[]}));
console.log('FINAL', JSON.stringify(fin));
await snap('final');
console.log('errors', errors);
await browser.close();

