import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ channel:'chromium', headless:true, args:['--enable-gpu','--ignore-gpu-blocklist','--use-angle=swiftshader'] });
const errors=[];
const page = await browser.newPage({ viewport:{width:1280,height:800}, deviceScaleFactor:1 });
page.on('pageerror', e => errors.push('PAGEERROR: '+e.message));
page.on('console', m => { if(m.type()==='error') errors.push('CONSOLE: '+m.text()); });
await page.goto('http://localhost:3000/', {waitUntil:'networkidle'});
await page.evaluate(()=>localStorage.clear());
await page.reload({waitUntil:'networkidle'});
await page.waitForTimeout(1200);

const info = () => page.evaluate(()=>({
  q:__mosslight.state.questIndex, prog:__mosslight.state.questProgress,
  title:document.querySelector('#questTitle').textContent,
  count:document.querySelector('#questCount').textContent,
  dew:__mosslight.state.resources.dew, pals:__mosslight.state.pals.length,
  warmth:Math.round(__mosslight.state.warmth),
  levelOpen:!document.querySelector('#levelUp').hidden,
  levelTitle:document.querySelector('#levelUpTitle').textContent
}));

// seed to the collect quest
await page.evaluate(()=>{ __mosslight.state.questIndex=6; __mosslight.state.questProgress=0; __mosslight.state.warmth=96; });
await page.waitForTimeout(2200);
console.log('seeded', await info());

// fill to 8 treasures
await page.evaluate(()=>{
  const cols=['dew','berries','sparks'];
  const n = 8-__mosslight.collectibles.length;
  for (let i=0;i<n;i++) __mosslight.spawnCollectible(cols[i%3], 0.8+(i%4)*0.6, 1.5+Math.floor(i/4)*0.6, 1);
});
await page.waitForTimeout(600);
let spots = await page.evaluate(()=>__mosslight.collectibles.map(c=>{const b=__mosslight.iso(__mosslight.view,c.c,c.r);return {x:b.x,y:b.y-8*__mosslight.view.scale};}));
console.log('collectibles', spots.length);
for (const sp of spots) { await page.mouse.click(sp.x,sp.y); await page.waitForTimeout(700); }
await page.waitForTimeout(2000);
console.log('after collect', await info());
await page.screenshot({path:'/tmp/opencode/shots/q2-collect.jpg', type:'jpeg', quality:72});

// wait for final hearth-level quest to auto-complete
await page.waitForTimeout(3200);
console.log('final', await info());
await page.screenshot({path:'/tmp/opencode/shots/q2-final.jpg', type:'jpeg', quality:72});

// now test Hearth lvl 4 (Yuzu) discovery
await page.evaluate(()=>{ __mosslight.state.warmth=145.9; });
const pos = await page.evaluate(()=>{const p=__mosslight.state.pals[0];const s=__mosslight.iso(__mosslight.view,p.x,p.y);return {x:s.x,y:s.y-40*__mosslight.view.scale};});
await page.mouse.click(pos.x,pos.y); await page.waitForTimeout(500);
await page.evaluate(()=>__mosslight.doPet(__mosslight.state.pals[0]));
await page.waitForTimeout(2400);
console.log('lvl4', await info());
await page.screenshot({path:'/tmp/opencode/shots/q2-level4.jpg', type:'jpeg', quality:72});
if (await page.locator('#levelUp').isVisible()) {
  await page.locator('#levelUpBtn').click();
  await page.waitForTimeout(1200);
}
console.log('yuzu', await page.evaluate(()=>__mosslight.state.pals.map(p=>p.species+'@'+p.x.toFixed(1)+','+p.y.toFixed(1))));
await page.screenshot({path:'/tmp/opencode/shots/q2-yuzu.jpg', type:'jpeg', quality:72});
console.log('errors', errors);
await browser.close();

